"use strict";
/* ================= CONCEPT MAPS ================= */
const CMAPS=[{"id": "heart-failure", "title": "Heart failure: from failing pump to bedside signs", "sys": "cvs", "intro": "Follows a failing left ventricle through rising filling pressures to the signs you can find at the bedside, and shows which signs carry real weight in a breathless patient. Each sign is tied to the physiology that produces it, so you remember why S3 and a raised JVP matter more than oedema.", "nodes": [{"id": "n1", "label": "Heart failure", "type": "diagnosis", "note": "A syndrome in which the heart cannot deliver adequate output at normal filling pressures; the bedside task is to find raised filling pressure and low output.", "link": "practice/hdpe/hf", "level": 0}, {"id": "n2", "label": "Reduced ejection fraction", "type": "mechanism", "note": "Systolic failure: a dilated, poorly contracting ventricle after infarction, cardiomyopathy or longstanding valve disease.", "link": null, "level": 1}, {"id": "n3", "label": "Stiff ventricle (HFpEF)", "type": "mechanism", "note": "Diastolic failure: a thick, non-compliant ventricle (hypertension, aortic stenosis, ischaemia) fills only at high pressure.", "link": null, "level": 1}, {"id": "n4", "label": "Raised LV filling pressure", "type": "mechanism", "note": "LVEDP above about 15 mmHg is transmitted back to the left atrium and pulmonary veins.", "link": null, "level": 2}, {"id": "n5", "label": "Pulmonary venous congestion", "type": "mechanism", "note": "High pulmonary capillary pressure leaks fluid into the interstitium and alveoli.", "link": null, "level": 3}, {"id": "n6", "label": "Raised right-sided pressure", "type": "mechanism", "note": "Pulmonary hypertension and RV failure raise right atrial pressure, which the jugular veins display directly.", "link": null, "level": 3}, {"id": "n7", "label": "Low cardiac output", "type": "mechanism", "note": "Poor forward flow causes fatigue, cool peripheries, narrow pulse pressure and renal hypoperfusion.", "link": null, "level": 2}, {"id": "n8", "label": "Orthopnoea and PND", "type": "history", "note": "Lying flat shifts blood centrally; orthopnoea has LR about 2 and PND about 2.6 for heart failure as the cause of dyspnoea.", "link": "learn/pres/dysp", "level": 4}, {"id": "n9", "label": "Third heart sound", "type": "sign", "note": "A low-pitched early diastolic sound from rapid filling of a non-compliant, volume-loaded ventricle; LR about 11 for LVEDP > 15 in the dyspnoeic patient.", "link": "signs/sign/s3", "level": 4}, {"id": "n10", "label": "Elevated JVP", "type": "sign", "note": "Venous column more than 3 cm above the sternal angle at 45 degrees; LR about 4 for heart failure in dyspnoea.", "link": "signs/sign/jvp", "level": 4}, {"id": "n11", "label": "Abdominojugular reflux", "type": "sign", "note": "Sustained JVP rise of 3 cm or more during 10 s of abdominal pressure; LR about 6 for raised left-sided filling pressure.", "link": "signs/sign/ajr", "level": 4}, {"id": "n12", "label": "Crackles", "type": "sign", "note": "Fine late inspiratory crackles at the bases from alveolar fluid; only modestly specific, as fibrosis and pneumonia produce them too.", "link": "signs/sign/crackles", "level": 4}, {"id": "n13", "label": "Displaced apex", "type": "sign", "note": "Apex beat lateral to the midclavicular line signals a dilated ventricle; LR about 5 for low ejection fraction.", "link": "signs/sign/apex-displaced", "level": 4}, {"id": "n14", "label": "Peripheral oedema", "type": "sign", "note": "Bilateral pitting oedema from raised venous pressure and sodium retention; common but weak (LR about 2) because many other causes exist.", "link": "signs/sign/oedema", "level": 4}, {"id": "n15", "label": "Fourth heart sound", "type": "sign", "note": "Late diastolic sound as the atrium forces blood into a stiff ventricle; marks diastolic dysfunction rather than fluid overload.", "link": "signs/sign/s4", "level": 4}, {"id": "n16", "label": "Cool mottled periphery", "type": "sign", "note": "Vasoconstriction to defend blood pressure; the 'cold and wet' profile that needs inotropes rather than diuretics alone.", "link": "signs/sign/passive-leg-mottling", "level": 4}, {"id": "n17", "label": "Pleural effusion", "type": "sign", "note": "Transudate, usually bilateral or right-sided, giving stony dullness and reduced breath sounds at a base.", "link": "signs/sign/percussion-dull", "level": 4}, {"id": "n18", "label": "BNP and echo", "type": "test", "note": "Natriuretic peptide excludes heart failure when normal; echocardiography defines ejection fraction, valves and filling pressure.", "link": null, "level": 4}], "edges": [{"from": "n1", "to": "n2", "label": "one form"}, {"from": "n1", "to": "n3", "label": "other form"}, {"from": "n2", "to": "n4", "label": "raises"}, {"from": "n3", "to": "n4", "label": "raises"}, {"from": "n2", "to": "n7", "label": "causes"}, {"from": "n4", "to": "n5", "label": "transmits to"}, {"from": "n5", "to": "n6", "label": "over time"}, {"from": "n4", "to": "n6", "label": "via RV"}, {"from": "n5", "to": "n8", "label": "produces"}, {"from": "n4", "to": "n9", "label": "produces"}, {"from": "n6", "to": "n10", "label": "raises"}, {"from": "n4", "to": "n11", "label": "unmasks"}, {"from": "n5", "to": "n12", "label": "produces"}, {"from": "n2", "to": "n13", "label": "dilates to"}, {"from": "n6", "to": "n14", "label": "causes"}, {"from": "n3", "to": "n15", "label": "produces"}, {"from": "n7", "to": "n16", "label": "produces"}, {"from": "n5", "to": "n17", "label": "leaks into"}, {"from": "n1", "to": "n18", "label": "confirmed by"}], "quiz": [{"q": "Which two bedside signs raise the probability of heart failure most in a breathless patient?", "a": "A third heart sound and an elevated JVP (with abdominojugular reflux)."}, {"q": "Why is peripheral oedema a weak sign for heart failure?", "a": "It has many other causes (venous disease, drugs, hypoalbuminaemia), so its LR is only about 2."}, {"q": "What does a fourth heart sound tell you about the ventricle?", "a": "It is stiff (diastolic dysfunction): the atrium is forcing blood into a non-compliant chamber."}]}, {"id": "chest-pain", "title": "Chest pain: separating the four killers", "sys": "cvs", "intro": "Acute coronary syndrome, aortic dissection, pulmonary embolism and tension pneumothorax all present with chest pain, and the history and a few targeted signs separate them within minutes. The map shows which question or sign points to which killer, and which features argue against ACS.", "nodes": [{"id": "n1", "label": "Acute chest pain", "type": "symptom", "note": "The first task is to exclude four time-critical causes before considering the benign majority.", "link": "learn/pres/chest", "level": 0}, {"id": "n2", "label": "Onset to peak", "type": "history", "note": "Seconds to maximal pain suggests dissection, PE or pneumothorax; pain that builds over minutes suggests ACS.", "link": null, "level": 1}, {"id": "n3", "label": "Character and radiation", "type": "history", "note": "Pressure radiating to both arms (LR about 4) or the right arm (LR about 5) favours MI; tearing pain to the back favours dissection (LR about 11).", "link": null, "level": 1}, {"id": "n4", "label": "Risk factors", "type": "history", "note": "Smoking, diabetes, hypertension, family history and cocaine for ACS; immobility, cancer, oestrogen and previous VTE for PE; Marfan, hypertension and known aneurysm for dissection.", "link": null, "level": 1}, {"id": "n5", "label": "Acute coronary syndrome", "type": "diagnosis", "note": "Plaque rupture and thrombosis; exertional, with sweating and vomiting, and similar to previous MI.", "link": null, "level": 2}, {"id": "n6", "label": "Aortic dissection", "type": "diagnosis", "note": "Intimal tear with a false lumen propagating along the aorta; may occlude branch vessels or rupture into the pericardium.", "link": null, "level": 2}, {"id": "n7", "label": "Pulmonary embolism", "type": "diagnosis", "note": "Thrombus in the pulmonary arteries causing pleuritic pain, dyspnoea, tachycardia and hypoxaemia.", "link": null, "level": 2}, {"id": "n8", "label": "Tension pneumothorax", "type": "diagnosis", "note": "Air trapped under pressure collapses the lung, shifts the mediastinum and obstructs venous return.", "link": null, "level": 2}, {"id": "n9", "label": "Pleuritic, positional, reproducible", "type": "history", "note": "Each argues against ACS (LR about 0.2 to 0.3) and points to pleura, pericardium or chest wall instead.", "link": null, "level": 2}, {"id": "n10", "label": "Inter-arm BP difference", "type": "sign", "note": "Systolic difference over 20 mmHg or a pulse deficit supports dissection (LR about 5), though absence does not exclude it.", "link": "signs/sign/bp-arms", "level": 3}, {"id": "n11", "label": "New AR murmur", "type": "sign", "note": "Early diastolic murmur from the dissection flap disrupting the aortic valve in proximal dissection.", "link": "signs/sign/ar-murmur", "level": 3}, {"id": "n12", "label": "Tracheal deviation", "type": "sign", "note": "Trachea pushed away from a tension pneumothorax; a late sign that follows hypotension and distended neck veins.", "link": "signs/sign/tracheal-deviation", "level": 3}, {"id": "n13", "label": "Absent breath sounds", "type": "sign", "note": "Silent hemithorax with hyperresonance on the affected side.", "link": "sounds/sound/absent-breath", "level": 3}, {"id": "n14", "label": "Tachycardia and hypoxaemia", "type": "sign", "note": "Resting tachycardia, raised respiratory rate and low saturations with a clear chest point to PE.", "link": "signs/sign/resp-rate", "level": 3}, {"id": "n15", "label": "Unilateral leg swelling", "type": "sign", "note": "DVT as the source of embolism; the Wells score formalises the pretest probability.", "link": "signs/sign/wells-dvt", "level": 3}, {"id": "n16", "label": "ECG within 10 minutes", "type": "test", "note": "ST elevation needs immediate reperfusion; a normal ECG does not exclude ACS and troponin is repeated.", "link": null, "level": 3}, {"id": "n17", "label": "CT angiography", "type": "test", "note": "CT aortogram for dissection and CT pulmonary angiogram for PE when pretest probability is not low; PERC and D-dimer exclude PE in low-risk patients.", "link": "signs/sign/wells-pe", "level": 3}, {"id": "n18", "label": "Pericarditis", "type": "diagnosis", "note": "Sharp pain worse lying flat and better sitting forward, with a friction rub; a frequent mimic once the killers are excluded.", "link": "sounds/sound/rub", "level": 2}], "edges": [{"from": "n1", "to": "n2", "label": "ask"}, {"from": "n1", "to": "n3", "label": "ask"}, {"from": "n1", "to": "n4", "label": "ask"}, {"from": "n2", "to": "n6", "label": "seconds"}, {"from": "n2", "to": "n7", "label": "seconds"}, {"from": "n2", "to": "n8", "label": "seconds"}, {"from": "n2", "to": "n5", "label": "minutes"}, {"from": "n3", "to": "n5", "label": "both arms"}, {"from": "n3", "to": "n6", "label": "tearing"}, {"from": "n4", "to": "n5", "label": "cardiac risk"}, {"from": "n4", "to": "n7", "label": "VTE risk"}, {"from": "n9", "to": "n5", "label": "argues against"}, {"from": "n9", "to": "n18", "label": "supports"}, {"from": "n6", "to": "n10", "label": "causes"}, {"from": "n6", "to": "n11", "label": "causes"}, {"from": "n8", "to": "n12", "label": "shifts"}, {"from": "n8", "to": "n13", "label": "silences"}, {"from": "n7", "to": "n14", "label": "causes"}, {"from": "n7", "to": "n15", "label": "source"}, {"from": "n5", "to": "n16", "label": "confirmed by"}, {"from": "n6", "to": "n17", "label": "confirmed by"}, {"from": "n7", "to": "n17", "label": "confirmed by"}], "quiz": [{"q": "Which radiation pattern raises the probability of MI the most?", "a": "Radiation to the right arm or to both arms (LR about 4 to 5)."}, {"q": "Name three historical features that argue against ACS.", "a": "Pleuritic pain, positional pain and pain reproduced by palpation."}, {"q": "Which bedside sign supports aortic dissection and what is its limitation?", "a": "Inter-arm systolic difference over 20 mmHg or a pulse deficit; absence does not exclude dissection."}]}, {"id": "shock", "title": "Shock: four mechanisms and the signs that reveal them", "sys": "gen", "intro": "Shock is inadequate tissue perfusion, and the four mechanisms (hypovolaemic, cardiogenic, obstructive, distributive) each leave a different combination of JVP, skin and fluid-responsiveness findings. The map links each type to its physiology and to the bedside tests that decide whether to give fluid.", "nodes": [{"id": "n1", "label": "Shock", "type": "diagnosis", "note": "Tissue hypoperfusion: hypotension is a late marker, so look for tachycardia, mottling, confusion, oliguria and lactate rise first.", "link": null, "level": 0}, {"id": "n2", "label": "Hypovolaemic", "type": "mechanism", "note": "Lost volume (haemorrhage, vomiting, diarrhoea, burns) reduces preload and stroke volume.", "link": null, "level": 1}, {"id": "n3", "label": "Cardiogenic", "type": "mechanism", "note": "Pump failure (MI, arrhythmia, valve rupture) reduces output despite high filling pressure.", "link": null, "level": 1}, {"id": "n4", "label": "Obstructive", "type": "mechanism", "note": "Tamponade, tension pneumothorax or massive PE block venous return or ventricular ejection.", "link": null, "level": 1}, {"id": "n5", "label": "Distributive", "type": "mechanism", "note": "Sepsis, anaphylaxis or neurogenic causes vasodilate and leak capillaries; output may be high early.", "link": null, "level": 1}, {"id": "n6", "label": "Low preload", "type": "mechanism", "note": "Empty veins: the JVP is flat and the heart responds to volume.", "link": null, "level": 2}, {"id": "n7", "label": "High venous pressure", "type": "mechanism", "note": "Blood dams back behind a failing or obstructed heart; the JVP rises and fluid may harm.", "link": null, "level": 2}, {"id": "n8", "label": "Vasoconstriction", "type": "mechanism", "note": "Sympathetic drive diverts blood from skin and gut to brain and heart: cool, pale, mottled skin.", "link": null, "level": 2}, {"id": "n9", "label": "Vasodilatation", "type": "mechanism", "note": "Warm, flushed peripheries with a bounding pulse and wide pulse pressure in early distributive shock.", "link": null, "level": 2}, {"id": "n10", "label": "Flat JVP", "type": "sign", "note": "Jugular vein not visible even lying flat; supports hypovolaemia or distributive shock.", "link": "signs/sign/jvp", "level": 3}, {"id": "n11", "label": "Raised JVP", "type": "sign", "note": "Distended neck veins in a hypotensive patient mean cardiogenic or obstructive shock until proven otherwise.", "link": "signs/sign/jvp", "level": 3}, {"id": "n12", "label": "Beck's triad", "type": "sign", "note": "Hypotension, raised JVP and quiet heart sounds; with pulsus paradoxus, tamponade is likely.", "link": "signs/sign/tamponade-signs", "level": 3}, {"id": "n13", "label": "Capillary refill > 2 s", "type": "sign", "note": "Delayed refill at the fingertip or knee reflects skin hypoperfusion; useful for trend and in children.", "link": "signs/sign/cap-refill", "level": 3}, {"id": "n14", "label": "Mottling", "type": "sign", "note": "Patchy purple discolouration spreading from the knees; the extent of the mottling score predicts mortality in septic shock.", "link": "signs/sign/passive-leg-mottling", "level": 3}, {"id": "n15", "label": "Shock index > 0.9", "type": "sign", "note": "Heart rate divided by systolic BP; detects occult shock before the blood pressure falls.", "link": "signs/sign/shock-index", "level": 3}, {"id": "n16", "label": "Postural change", "type": "sign", "note": "Pulse rise of 30 or more on standing, or inability to stand from dizziness, indicates large acute blood loss.", "link": "signs/sign/postural", "level": 3}, {"id": "n17", "label": "Passive leg raise", "type": "test", "note": "Lifting the legs to 45 degrees returns about 300 mL to the heart; a 10% rise in stroke volume or pulse pressure predicts fluid responsiveness.", "link": "signs/sign/plr", "level": 4}, {"id": "n18", "label": "Lactate", "type": "test", "note": "Above 2 mmol/L marks hypoperfusion; above 4 with hypotension defines septic shock. Trend it after resuscitation.", "link": null, "level": 4}, {"id": "n19", "label": "Fluid or vasopressor?", "type": "decision", "note": "Give fluid when the JVP is flat and PLR is positive; start vasopressors early in distributive shock and avoid large fluid loads when the JVP is high.", "link": null, "level": 4}], "edges": [{"from": "n1", "to": "n2", "label": "type"}, {"from": "n1", "to": "n3", "label": "type"}, {"from": "n1", "to": "n4", "label": "type"}, {"from": "n1", "to": "n5", "label": "type"}, {"from": "n2", "to": "n6", "label": "causes"}, {"from": "n5", "to": "n6", "label": "relative"}, {"from": "n3", "to": "n7", "label": "causes"}, {"from": "n4", "to": "n7", "label": "causes"}, {"from": "n2", "to": "n8", "label": "triggers"}, {"from": "n3", "to": "n8", "label": "triggers"}, {"from": "n5", "to": "n9", "label": "causes"}, {"from": "n6", "to": "n10", "label": "shows as"}, {"from": "n7", "to": "n11", "label": "shows as"}, {"from": "n4", "to": "n12", "label": "tamponade"}, {"from": "n8", "to": "n13", "label": "shows as"}, {"from": "n8", "to": "n14", "label": "shows as"}, {"from": "n1", "to": "n15", "label": "detected by"}, {"from": "n2", "to": "n16", "label": "shows as"}, {"from": "n6", "to": "n17", "label": "predicts response"}, {"from": "n1", "to": "n18", "label": "graded by"}, {"from": "n17", "to": "n19", "label": "guides"}, {"from": "n11", "to": "n19", "label": "guides"}, {"from": "n10", "to": "n19", "label": "guides"}], "quiz": [{"q": "A hypotensive patient has distended neck veins. Which two shock mechanisms remain?", "a": "Cardiogenic and obstructive (tamponade, tension pneumothorax, massive PE)."}, {"q": "What change on passive leg raise predicts fluid responsiveness?", "a": "A rise of about 10% in stroke volume (or pulse pressure as a surrogate) within 60 to 90 seconds."}, {"q": "Why is the shock index useful?", "a": "HR divided by systolic BP above 0.9 reveals occult shock before blood pressure falls."}]}, {"id": "dyspnoea", "title": "Breathlessness: six branches and their signs", "sys": "resp", "intro": "Breathlessness comes from the airway, the lung, the pleura, the heart, the blood or the acid-base state, and each branch has characteristic signs. The map sorts the common emergencies by branch so the examination becomes a directed search rather than a routine.", "nodes": [{"id": "n1", "label": "Breathlessness", "type": "symptom", "note": "Ask speed of onset, exercise tolerance in stairs, orthopnoea and PND, wheeze, sputum, chest pain and fever.", "link": "learn/pres/dysp", "level": 0}, {"id": "n2", "label": "Upper airway", "type": "anatomy", "note": "Obstruction above the carina: anaphylaxis, epiglottitis, foreign body, tumour.", "link": null, "level": 1}, {"id": "n3", "label": "Lower airways", "type": "anatomy", "note": "Asthma and COPD: narrowed bronchi with prolonged expiration.", "link": null, "level": 1}, {"id": "n4", "label": "Lung parenchyma", "type": "anatomy", "note": "Consolidation, oedema, fibrosis: the gas-exchanging tissue is flooded or stiff.", "link": null, "level": 1}, {"id": "n5", "label": "Pleura", "type": "anatomy", "note": "Fluid or air in the pleural space compresses the lung.", "link": null, "level": 1}, {"id": "n6", "label": "Heart", "type": "anatomy", "note": "Raised left-sided pressure floods the lung; arrhythmia or tamponade cut output.", "link": null, "level": 1}, {"id": "n7", "label": "Blood and metabolism", "type": "anatomy", "note": "Anaemia reduces oxygen carriage; acidosis drives ventilation without lung disease.", "link": null, "level": 1}, {"id": "n8", "label": "Stridor", "type": "sign", "note": "Harsh inspiratory noise from the larynx or trachea; an airway emergency.", "link": "signs/sign/stridor-sign", "level": 2}, {"id": "n9", "label": "Wheeze and long expiration", "type": "sign", "note": "Polyphonic expiratory wheeze with forced expiratory time over 9 s marks airflow obstruction.", "link": "signs/sign/fet", "level": 2}, {"id": "n10", "label": "Hyperinflation", "type": "sign", "note": "Hoover's sign and a low laryngeal height show the flattened diaphragm of COPD.", "link": "signs/sign/hoover", "level": 2}, {"id": "n11", "label": "Peak flow", "type": "test", "note": "Compared with the patient's best: below 50% is severe, below 33% is life-threatening asthma.", "link": "signs/sign/peak-flow", "level": 3}, {"id": "n12", "label": "Consolidation", "type": "sign", "note": "Bronchial breathing, increased fremitus and egophony over a dull area: pneumonia.", "link": "signs/sign/bronchial-breathing", "level": 2}, {"id": "n13", "label": "Crackles", "type": "sign", "note": "Fine late inspiratory crackles at the bases: pulmonary oedema or fibrosis; coarse crackles: secretions.", "link": "signs/sign/crackles", "level": 2}, {"id": "n14", "label": "Stony dullness", "type": "sign", "note": "Effusion: dull percussion, reduced fremitus and absent breath sounds at a base.", "link": "signs/sign/percussion-dull", "level": 2}, {"id": "n15", "label": "Hyperresonance", "type": "sign", "note": "Pneumothorax: resonant, silent hemithorax, trachea deviated away if under tension.", "link": "signs/sign/tracheal-deviation", "level": 2}, {"id": "n16", "label": "Raised JVP and S3", "type": "sign", "note": "Point to heart failure as the cause; together with orthopnoea they outperform crackles and oedema.", "link": "signs/sign/s3", "level": 2}, {"id": "n17", "label": "Conjunctival pallor", "type": "sign", "note": "Suggests haemoglobin at or below 9 g/dL; breathlessness on exertion with a clear chest.", "link": "signs/sign/conj-pallor", "level": 2}, {"id": "n18", "label": "Kussmaul breathing", "type": "sign", "note": "Deep, sighing respiration of metabolic acidosis (DKA, uraemia, sepsis, poisoning).", "link": "signs/sign/kussmaul-breathing", "level": 2}, {"id": "n19", "label": "Respiratory failure warning", "type": "decision", "note": "Respiratory rate over 30, SpO2 below 92%, inability to speak in sentences, silent chest, paradoxical abdominal movement or new confusion mean the patient is tiring.", "link": "signs/sign/paradox-abdomen", "level": 3}, {"id": "n20", "label": "CURB-65 and PERC", "type": "test", "note": "CURB-65 grades pneumonia severity; PERC excludes PE in low-risk patients without a D-dimer.", "link": "signs/sign/curb65", "level": 3}], "edges": [{"from": "n1", "to": "n2", "label": "branch"}, {"from": "n1", "to": "n3", "label": "branch"}, {"from": "n1", "to": "n4", "label": "branch"}, {"from": "n1", "to": "n5", "label": "branch"}, {"from": "n1", "to": "n6", "label": "branch"}, {"from": "n1", "to": "n7", "label": "branch"}, {"from": "n2", "to": "n8", "label": "produces"}, {"from": "n3", "to": "n9", "label": "produces"}, {"from": "n3", "to": "n10", "label": "COPD"}, {"from": "n9", "to": "n11", "label": "graded by"}, {"from": "n4", "to": "n12", "label": "pneumonia"}, {"from": "n4", "to": "n13", "label": "oedema/fibrosis"}, {"from": "n5", "to": "n14", "label": "effusion"}, {"from": "n5", "to": "n15", "label": "pneumothorax"}, {"from": "n6", "to": "n16", "label": "produces"}, {"from": "n6", "to": "n13", "label": "oedema"}, {"from": "n7", "to": "n17", "label": "anaemia"}, {"from": "n7", "to": "n18", "label": "acidosis"}, {"from": "n1", "to": "n19", "label": "watch for"}, {"from": "n12", "to": "n20", "label": "graded by"}], "quiz": [{"q": "What does Kussmaul breathing signal in a breathless patient with a clear chest?", "a": "Metabolic acidosis (DKA, uraemia, sepsis, poisoning) driving compensatory hyperventilation."}, {"q": "Which findings distinguish consolidation from effusion at a dull base?", "a": "Consolidation has bronchial breathing, increased fremitus and egophony; effusion has reduced fremitus and absent breath sounds."}, {"q": "Name four signs that the breathless patient is tiring.", "a": "Inability to speak in sentences, silent chest, paradoxical abdominal movement, new confusion (also RR over 30, SpO2 below 92%)."}]}, {"id": "jvp-physiology", "title": "The JVP: waves, reflux and what raises it", "sys": "cvs", "intro": "The internal jugular vein is a manometer connected to the right atrium, so its height and waveform report right-sided pressure and the mechanics of each cardiac cycle. The map explains the a, c, x, v and y components, the abnormal patterns, the abdominojugular and Kussmaul manoeuvres, and the conditions that raise the column.", "nodes": [{"id": "n1", "label": "Jugular venous pressure", "type": "anatomy", "note": "The internal jugular vein runs beneath sternocleidomastoid and has no valves between it and the right atrium; measure the top of the pulsation vertically above the sternal angle.", "link": "signs/sign/jvp", "level": 0}, {"id": "n2", "label": "Right atrial pressure", "type": "mechanism", "note": "Normal is 0 to 8 mmHg; the sternal angle sits about 5 cm above the mid right atrium, so more than 3 cm above the angle is raised.", "link": null, "level": 1}, {"id": "n3", "label": "a wave", "type": "mechanism", "note": "Atrial contraction just before S1; absent in atrial fibrillation.", "link": null, "level": 2}, {"id": "n4", "label": "Cannon a waves", "type": "sign", "note": "Giant a waves when the atrium contracts against a closed tricuspid valve: complete heart block, VT, AV dissociation.", "link": null, "level": 3}, {"id": "n5", "label": "Large a waves", "type": "sign", "note": "Regular giant a waves from a stiff RV or tricuspid stenosis: pulmonary hypertension, pulmonary stenosis.", "link": null, "level": 3}, {"id": "n6", "label": "x descent", "type": "mechanism", "note": "Atrial relaxation and downward movement of the tricuspid ring in systole; the dominant descent in health.", "link": null, "level": 2}, {"id": "n7", "label": "v wave", "type": "mechanism", "note": "Passive atrial filling against a closed tricuspid valve in late systole.", "link": null, "level": 2}, {"id": "n8", "label": "Giant v waves", "type": "sign", "note": "Tricuspid regurgitation fills the atrium directly in systole: a pulsatile liver and a 'cv' wave.", "link": "sounds/sound/tr", "level": 3}, {"id": "n9", "label": "y descent", "type": "mechanism", "note": "Tricuspid valve opens and the atrium empties into the ventricle in early diastole.", "link": null, "level": 2}, {"id": "n10", "label": "Rapid y (Friedreich)", "type": "sign", "note": "Steep y descent with raised pressure: constrictive pericarditis, where early filling is brisk and then abruptly halted.", "link": null, "level": 3}, {"id": "n11", "label": "Blunted y", "type": "sign", "note": "Tamponade: the compressed ventricle cannot fill in early diastole, so the y descent disappears while x persists.", "link": "signs/sign/tamponade-signs", "level": 3}, {"id": "n12", "label": "Abdominojugular reflux", "type": "test", "note": "Press the mid-abdomen for 10 s: a sustained rise of 3 cm or more means the right heart cannot accept the extra venous return; LR about 6 for raised left-sided filling pressure.", "link": "signs/sign/ajr", "level": 2}, {"id": "n13", "label": "Kussmaul's sign", "type": "sign", "note": "JVP rises on inspiration instead of falling: the right ventricle cannot accommodate increased venous return (constriction, RV infarction, restrictive cardiomyopathy).", "link": "signs/sign/kussmaul-sign", "level": 2}, {"id": "n14", "label": "Heart failure", "type": "diagnosis", "note": "The commonest cause of a raised JVP; LR about 4 for heart failure in the dyspnoeic patient.", "link": "practice/hdpe/hf", "level": 3}, {"id": "n15", "label": "Volume overload", "type": "diagnosis", "note": "Renal failure or iatrogenic fluid: raised JVP with a normal heart.", "link": null, "level": 3}, {"id": "n16", "label": "SVC obstruction", "type": "diagnosis", "note": "Non-pulsatile, fixed distension with facial swelling; Pemberton's sign on raising the arms.", "link": "signs/sign/pemberton", "level": 3}, {"id": "n17", "label": "Hepatojugular link", "type": "mechanism", "note": "The same raised venous pressure produces hepatomegaly, ascites and oedema downstream.", "link": "signs/sign/oedema", "level": 3}], "edges": [{"from": "n1", "to": "n2", "label": "reflects"}, {"from": "n2", "to": "n3", "label": "wave"}, {"from": "n2", "to": "n6", "label": "descent"}, {"from": "n2", "to": "n7", "label": "wave"}, {"from": "n2", "to": "n9", "label": "descent"}, {"from": "n3", "to": "n4", "label": "exaggerated"}, {"from": "n3", "to": "n5", "label": "exaggerated"}, {"from": "n7", "to": "n8", "label": "exaggerated"}, {"from": "n9", "to": "n10", "label": "exaggerated"}, {"from": "n9", "to": "n11", "label": "abolished"}, {"from": "n1", "to": "n12", "label": "manoeuvre"}, {"from": "n1", "to": "n13", "label": "inspiration"}, {"from": "n12", "to": "n14", "label": "supports"}, {"from": "n13", "to": "n10", "label": "same cause"}, {"from": "n14", "to": "n1", "label": "raises"}, {"from": "n15", "to": "n1", "label": "raises"}, {"from": "n16", "to": "n1", "label": "raises"}, {"from": "n14", "to": "n17", "label": "causes"}], "quiz": [{"q": "What causes cannon a waves?", "a": "Atrial contraction against a closed tricuspid valve, as in complete heart block or AV dissociation."}, {"q": "How do the y descents of tamponade and constriction differ?", "a": "Tamponade blunts or abolishes the y descent; constriction produces a rapid, steep y descent."}, {"q": "What is a positive abdominojugular reflux and what does it indicate?", "a": "A sustained JVP rise of 3 cm or more during 10 s of abdominal pressure; it indicates raised left-sided filling pressure (heart failure)."}]}, {"id": "murmurs", "title": "Murmurs: timing, site and manoeuvres to the lesion", "sys": "cvs", "intro": "A murmur is classified by where it sits in the cardiac cycle, where it is loudest, where it radiates and how it changes with breathing, Valsalva and handgrip. The map walks from these observable properties to the valve lesions and lets you listen to each one.", "nodes": [{"id": "n1", "label": "Murmur heard", "type": "sign", "note": "Turbulent flow across a valve or defect; decide timing first, then site, radiation, pitch and response to manoeuvres.", "link": "sounds/sound/normal", "level": 0}, {"id": "n2", "label": "Systolic", "type": "mechanism", "note": "Between S1 and S2: ejection (crescendo-decrescendo) or regurgitant (holosystolic).", "link": null, "level": 1}, {"id": "n3", "label": "Diastolic", "type": "mechanism", "note": "Between S2 and S1: always pathological; early decrescendo (regurgitant) or mid-diastolic rumble (stenotic).", "link": null, "level": 1}, {"id": "n4", "label": "Continuous", "type": "mechanism", "note": "Through S2: patent ductus arteriosus or an arteriovenous fistula.", "link": "sounds/sound/pda", "level": 1}, {"id": "n5", "label": "Aortic stenosis", "type": "diagnosis", "note": "Harsh ejection murmur at the right upper sternal edge radiating to the carotids; severe when A2 is soft and the carotid upstroke is slow.", "link": "sounds/sound/as", "level": 2}, {"id": "n6", "label": "Mitral regurgitation", "type": "diagnosis", "note": "Blowing holosystolic apical murmur radiating to the axilla; louder with handgrip.", "link": "sounds/sound/mr", "level": 2}, {"id": "n7", "label": "HOCM", "type": "diagnosis", "note": "Ejection murmur at the left sternal edge that gets louder with Valsalva and standing, softer with squatting and handgrip.", "link": "sounds/sound/hocm", "level": 2}, {"id": "n8", "label": "Mitral valve prolapse", "type": "diagnosis", "note": "Mid-systolic click then late systolic murmur; Valsalva moves the click earlier and lengthens the murmur.", "link": "sounds/sound/mvp", "level": 2}, {"id": "n9", "label": "Tricuspid regurgitation", "type": "diagnosis", "note": "Holosystolic murmur at the lower left sternal edge that increases on inspiration, with giant v waves.", "link": "sounds/sound/tr", "level": 2}, {"id": "n10", "label": "VSD", "type": "diagnosis", "note": "Loud harsh holosystolic murmur with thrill at the lower left sternal edge; new after anterior MI means septal rupture.", "link": "sounds/sound/vsd", "level": 2}, {"id": "n11", "label": "Aortic regurgitation", "type": "diagnosis", "note": "Early diastolic decrescendo at the left sternal edge, heard best sitting forward in expiration; wide pulse pressure and peripheral eponyms.", "link": "sounds/sound/ar", "level": 2}, {"id": "n12", "label": "Mitral stenosis", "type": "diagnosis", "note": "Opening snap then low-pitched mid-diastolic rumble at the apex with the bell in left lateral position; loud S1.", "link": "sounds/sound/ms", "level": 2}, {"id": "n13", "label": "Innocent flow murmur", "type": "diagnosis", "note": "Soft, short, mid-systolic, no radiation, normal S2, no symptoms; typical in pregnancy, fever and children.", "link": "sounds/sound/innocent", "level": 2}, {"id": "n14", "label": "Valsalva", "type": "test", "note": "Reduces venous return: nearly all murmurs soften, but HOCM gets louder and MVP's click moves earlier.", "link": "signs/sign/valsalva-murmur", "level": 3}, {"id": "n15", "label": "Sustained handgrip", "type": "test", "note": "Raises afterload: MR, AR and VSD get louder; AS and HOCM get softer.", "link": "signs/sign/handgrip", "level": 3}, {"id": "n16", "label": "Inspiration", "type": "test", "note": "Increases right-sided flow: right-sided murmurs (TR, PS) get louder (Carvallo's sign).", "link": null, "level": 3}, {"id": "n17", "label": "Carotid upstroke", "type": "sign", "note": "Slow-rising, delayed carotid pulse with a soft A2 marks severe AS.", "link": "signs/sign/carotid-upstroke", "level": 3}, {"id": "n18", "label": "Peripheral AR signs", "type": "sign", "note": "Corrigan's collapsing pulse, Quincke's nail pulsation and de Musset's head nodding reflect the wide pulse pressure of severe AR.", "link": "signs/sign/ar-eponyms", "level": 3}, {"id": "n19", "label": "Echocardiography", "type": "test", "note": "Every diastolic, continuous, loud (grade 3 or more) or symptomatic murmur gets an echo.", "link": null, "level": 3}], "edges": [{"from": "n1", "to": "n2", "label": "timing"}, {"from": "n1", "to": "n3", "label": "timing"}, {"from": "n1", "to": "n4", "label": "timing"}, {"from": "n2", "to": "n5", "label": "ejection"}, {"from": "n2", "to": "n7", "label": "ejection"}, {"from": "n2", "to": "n13", "label": "ejection"}, {"from": "n2", "to": "n6", "label": "holosystolic"}, {"from": "n2", "to": "n9", "label": "holosystolic"}, {"from": "n2", "to": "n10", "label": "holosystolic"}, {"from": "n2", "to": "n8", "label": "late systolic"}, {"from": "n3", "to": "n11", "label": "early"}, {"from": "n3", "to": "n12", "label": "mid-diastolic"}, {"from": "n14", "to": "n7", "label": "louder"}, {"from": "n14", "to": "n8", "label": "earlier click"}, {"from": "n15", "to": "n6", "label": "louder"}, {"from": "n15", "to": "n11", "label": "louder"}, {"from": "n15", "to": "n5", "label": "softer"}, {"from": "n16", "to": "n9", "label": "louder"}, {"from": "n5", "to": "n17", "label": "severe when"}, {"from": "n11", "to": "n18", "label": "severe when"}, {"from": "n3", "to": "n19", "label": "always"}, {"from": "n2", "to": "n19", "label": "if loud"}], "quiz": [{"q": "Which murmur gets louder with Valsalva, and why?", "a": "HOCM: reduced venous return shrinks the ventricle and worsens outflow obstruction."}, {"q": "How does handgrip separate aortic stenosis from mitral regurgitation?", "a": "Raised afterload makes MR louder and AS softer."}, {"q": "Which features of an aortic stenosis murmur indicate severe disease?", "a": "Slow-rising, delayed carotid upstroke and a soft or absent A2 (late-peaking murmur)."}]}, {"id": "pneumonia-vs-effusion-vs-pneumothorax", "title": "Dull or silent chest: consolidation, effusion or air?", "sys": "resp", "intro": "Percussion, fremitus, breath sounds and tracheal position together identify what fills the hemithorax. The map shows how each pathology changes sound transmission and resonance so you can predict the findings rather than memorise them.", "nodes": [{"id": "n1", "label": "Abnormal hemithorax", "type": "symptom", "note": "One side sounds or feels different: decide between solid lung, fluid and air using four properties.", "link": null, "level": 0}, {"id": "n2", "label": "Consolidation", "type": "diagnosis", "note": "Alveoli filled with exudate but airways patent: solid lung transmits sound well.", "link": "practice/hdpe/pna", "level": 1}, {"id": "n3", "label": "Pleural effusion", "type": "diagnosis", "note": "Fluid between lung and chest wall: blocks sound and vibration, dull to percussion.", "link": "practice/hdpe/eff", "level": 1}, {"id": "n4", "label": "Pneumothorax", "type": "diagnosis", "note": "Air in the pleural space: collapses the lung, hyperresonant, sound and vibration absent.", "link": null, "level": 1}, {"id": "n5", "label": "Sound transmission", "type": "mechanism", "note": "Solid tissue conducts high-frequency voice sounds to the chest wall; fluid and air block them.", "link": null, "level": 2}, {"id": "n6", "label": "Resonance", "type": "mechanism", "note": "Percussion note depends on the air content under the pleximeter finger: solid or fluid is dull, excess air is hyperresonant.", "link": null, "level": 2}, {"id": "n7", "label": "Mediastinal shift", "type": "mechanism", "note": "Large volumes push the trachea away; collapse and fibrosis pull it toward the lesion.", "link": null, "level": 2}, {"id": "n8", "label": "Bronchial breathing", "type": "sign", "note": "Hollow, high-pitched breath sounds with an expiratory phase equal to inspiration, heard peripherally over consolidation.", "link": "signs/sign/bronchial-breathing", "level": 3}, {"id": "n9", "label": "Increased fremitus", "type": "sign", "note": "Vocal vibrations are stronger over consolidation; reduced or absent over effusion and pneumothorax.", "link": "signs/sign/fremitus", "level": 3}, {"id": "n10", "label": "Egophony", "type": "sign", "note": "'E' sounds like 'A' over consolidation (LR about 4 for pneumonia).", "link": "signs/sign/egophony", "level": 3}, {"id": "n11", "label": "Whispered pectoriloquy", "type": "sign", "note": "Whispered words heard clearly through consolidated lung.", "link": "signs/sign/whisper", "level": 3}, {"id": "n12", "label": "Stony dullness", "type": "sign", "note": "Flat, absolute dullness over fluid; the level may shift with position.", "link": "signs/sign/percussion-dull", "level": 3}, {"id": "n13", "label": "Reduced expansion", "type": "sign", "note": "The affected side moves less in effusion, consolidation and pneumothorax alike; asymmetry localises the side.", "link": "signs/sign/chest-expansion", "level": 3}, {"id": "n14", "label": "Absent breath sounds", "type": "sign", "note": "Silence over an effusion or pneumothorax; crackles and bronchial breathing over pneumonia.", "link": "sounds/sound/absent-breath", "level": 3}, {"id": "n15", "label": "Hyperresonance", "type": "sign", "note": "Drum-like percussion over a pneumothorax; compare with the other side.", "link": "signs/sign/percussion-dull", "level": 3}, {"id": "n16", "label": "Tracheal deviation", "type": "sign", "note": "Away from a large effusion or tension pneumothorax; toward collapse. Tension is a clinical diagnosis: decompress before imaging.", "link": "signs/sign/tracheal-deviation", "level": 3}, {"id": "n17", "label": "Diaphragm excursion", "type": "test", "note": "Percussed level moves normally on the healthy side but not over an effusion.", "link": "signs/sign/auscultatory-percussion", "level": 4}, {"id": "n18", "label": "Chest X-ray or ultrasound", "type": "test", "note": "Ultrasound detects small effusions and pneumothorax faster than X-ray; X-ray shows consolidation and the meniscus.", "link": null, "level": 4}], "edges": [{"from": "n1", "to": "n2", "label": "solid"}, {"from": "n1", "to": "n3", "label": "fluid"}, {"from": "n1", "to": "n4", "label": "air"}, {"from": "n2", "to": "n5", "label": "increases"}, {"from": "n3", "to": "n5", "label": "blocks"}, {"from": "n4", "to": "n5", "label": "blocks"}, {"from": "n2", "to": "n6", "label": "dull"}, {"from": "n3", "to": "n6", "label": "stony dull"}, {"from": "n4", "to": "n6", "label": "hyperresonant"}, {"from": "n3", "to": "n7", "label": "pushes away"}, {"from": "n4", "to": "n7", "label": "pushes if tension"}, {"from": "n5", "to": "n8", "label": "consolidation"}, {"from": "n5", "to": "n9", "label": "up or down"}, {"from": "n5", "to": "n10", "label": "consolidation"}, {"from": "n5", "to": "n11", "label": "consolidation"}, {"from": "n6", "to": "n12", "label": "effusion"}, {"from": "n6", "to": "n15", "label": "pneumothorax"}, {"from": "n1", "to": "n13", "label": "any side"}, {"from": "n5", "to": "n14", "label": "blocked"}, {"from": "n7", "to": "n16", "label": "shows as"}, {"from": "n3", "to": "n17", "label": "fixes"}, {"from": "n1", "to": "n18", "label": "confirm"}], "quiz": [{"q": "Why is fremitus increased over consolidation but reduced over an effusion?", "a": "Solid lung transmits vocal vibration to the chest wall; a layer of fluid blocks it."}, {"q": "A dull base with bronchial breathing and egophony: what is it?", "a": "Consolidation (pneumonia)."}, {"q": "Which way does the trachea move with a tension pneumothorax and with lobar collapse?", "a": "Away from a tension pneumothorax; toward a collapse."}]}, {"id": "acute-abdomen", "title": "Acute abdomen: from pain type to the five diagnoses", "sys": "abd", "intro": "Visceral pain is dull and midline; parietal pain is sharp, localised and produces peritoneal signs. The map follows pain quality and migration through the specific signs to appendicitis, cholecystitis, peritonitis, obstruction and ruptured aneurysm.", "nodes": [{"id": "n1", "label": "Acute abdominal pain", "type": "symptom", "note": "Site now and at onset, character, vomiting before or after pain, flatus and last bowel movement; pregnancy test in every woman of reproductive age.", "link": "learn/pres/abdo", "level": 0}, {"id": "n2", "label": "Visceral pain", "type": "mechanism", "note": "Stretch or ischaemia of a hollow organ: dull, poorly localised, midline (epigastric foregut, periumbilical midgut, suprapubic hindgut); patient restless.", "link": null, "level": 1}, {"id": "n3", "label": "Parietal pain", "type": "mechanism", "note": "Inflamed parietal peritoneum: sharp, localised, worse with movement and cough; patient lies still.", "link": null, "level": 1}, {"id": "n4", "label": "Colic", "type": "mechanism", "note": "Waves of visceral pain from a peristalsing obstructed tube: bowel, ureter, biliary tree.", "link": null, "level": 2}, {"id": "n5", "label": "Migration to the RLQ", "type": "history", "note": "Periumbilical then right iliac fossa pain: the appendix irritates the parietal peritoneum as it inflames (LR about 3).", "link": null, "level": 2}, {"id": "n6", "label": "Peritonism", "type": "sign", "note": "Guarding, rigidity, rebound and percussion or cough tenderness mark local or generalised peritonitis.", "link": "signs/sign/rebound", "level": 2}, {"id": "n7", "label": "Appendicitis", "type": "diagnosis", "note": "Pain before vomiting, anorexia, migration and RLQ tenderness; the Alvarado score combines them.", "link": "practice/hdpe/app", "level": 3}, {"id": "n8", "label": "Cholecystitis", "type": "diagnosis", "note": "Constant RUQ pain after fatty food with fever; Murphy's sign has LR about 3.", "link": "practice/hdpe/chole", "level": 3}, {"id": "n9", "label": "Generalised peritonitis", "type": "diagnosis", "note": "Perforation, ischaemia or pancreatitis: board-like rigidity, silent abdomen, shock.", "link": null, "level": 3}, {"id": "n10", "label": "Bowel obstruction", "type": "diagnosis", "note": "Colicky pain, distension, vomiting and absolute constipation; tinkling then absent bowel sounds.", "link": null, "level": 3}, {"id": "n11", "label": "Ruptured AAA", "type": "diagnosis", "note": "Sudden severe abdominal or back pain with collapse in a patient over 60; a pulsatile mass may be the only sign.", "link": null, "level": 3}, {"id": "n12", "label": "McBurney tenderness", "type": "sign", "note": "Maximal tenderness two-thirds along the line from umbilicus to ASIS.", "link": "signs/sign/rlq-tender", "level": 4}, {"id": "n13", "label": "Rovsing and psoas signs", "type": "sign", "note": "LLQ pressure producing RLQ pain; hip extension pain from a retrocaecal appendix on the psoas.", "link": "signs/sign/rovsing", "level": 4}, {"id": "n14", "label": "Murphy's sign", "type": "sign", "note": "Inspiratory arrest as the inflamed gallbladder meets the examining hand under the right costal margin.", "link": "signs/sign/murphy", "level": 4}, {"id": "n15", "label": "Rigidity and cough test", "type": "sign", "note": "Involuntary guarding and pain on coughing or heel drop reflect generalised peritoneal inflammation.", "link": "signs/sign/cough-test", "level": 4}, {"id": "n16", "label": "Bowel sounds", "type": "sign", "note": "High-pitched tinkling early in obstruction, absent in ileus and late obstruction.", "link": "signs/sign/bowel-sounds", "level": 4}, {"id": "n17", "label": "Expansile pulsatile mass", "type": "sign", "note": "A mass that pushes the fingers apart with each beat; palpation detects most aneurysms over 5 cm.", "link": "signs/sign/aaa-palp", "level": 4}, {"id": "n18", "label": "Hernial orifices and DRE", "type": "sign", "note": "Irreducible hernia as a cause of obstruction; rectal examination for blood, masses or impaction.", "link": "signs/sign/hernia-cough", "level": 4}, {"id": "n19", "label": "Imaging decision", "type": "decision", "note": "Ultrasound first for RUQ pain, AAA and pelvis; CT for suspected obstruction, perforation, pancreatitis or undifferentiated pain in older patients.", "link": null, "level": 4}], "edges": [{"from": "n1", "to": "n2", "label": "dull midline"}, {"from": "n1", "to": "n3", "label": "sharp localised"}, {"from": "n2", "to": "n4", "label": "intermittent"}, {"from": "n2", "to": "n5", "label": "then"}, {"from": "n3", "to": "n6", "label": "produces"}, {"from": "n5", "to": "n7", "label": "classic"}, {"from": "n6", "to": "n7", "label": "local"}, {"from": "n6", "to": "n8", "label": "local"}, {"from": "n6", "to": "n9", "label": "generalised"}, {"from": "n4", "to": "n10", "label": "bowel"}, {"from": "n4", "to": "n8", "label": "biliary"}, {"from": "n1", "to": "n11", "label": "sudden, shocked"}, {"from": "n7", "to": "n12", "label": "sign"}, {"from": "n7", "to": "n13", "label": "sign"}, {"from": "n8", "to": "n14", "label": "sign"}, {"from": "n9", "to": "n15", "label": "sign"}, {"from": "n10", "to": "n16", "label": "sign"}, {"from": "n11", "to": "n17", "label": "sign"}, {"from": "n10", "to": "n18", "label": "check"}, {"from": "n7", "to": "n19", "label": "then"}, {"from": "n9", "to": "n19", "label": "then"}, {"from": "n10", "to": "n19", "label": "then"}, {"from": "n11", "to": "n19", "label": "then"}], "quiz": [{"q": "Why does appendicitis pain migrate from the periumbilical region to the right lower quadrant?", "a": "Early visceral (midgut) pain is referred to the umbilicus; once the parietal peritoneum is inflamed, pain localises to the RLQ."}, {"q": "What is Murphy's sign and which diagnosis does it support?", "a": "Inspiratory arrest on palpation under the right costal margin; acute cholecystitis."}, {"q": "Which bedside finding should prompt immediate concern for ruptured AAA in a collapsed older patient?", "a": "An expansile pulsatile abdominal mass (with sudden abdominal or back pain)."}]}, {"id": "gi-bleed-and-liver", "title": "Liver disease and GI bleeding: stigmata to portal hypertension", "sys": "abd", "intro": "Chronic liver disease leaves signs on the hands, face and chest; portal hypertension adds varices, splenomegaly and ascites; and decompensation shows as jaundice, encephalopathy and bleeding. The map connects each sign to its mechanism and to the bedside assessment of a GI bleed.", "nodes": [{"id": "n1", "label": "Chronic liver disease", "type": "diagnosis", "note": "Cirrhosis from alcohol, viral hepatitis or fatty liver: loss of synthetic function and distorted architecture.", "link": null, "level": 0}, {"id": "n2", "label": "Reduced oestrogen clearance", "type": "mechanism", "note": "The failing liver cannot metabolise oestrogens: vascular and feminising changes follow.", "link": null, "level": 1}, {"id": "n3", "label": "Portal hypertension", "type": "mechanism", "note": "Fibrosis raises resistance to portal flow; blood diverts through collaterals and the spleen congests.", "link": null, "level": 1}, {"id": "n4", "label": "Reduced synthesis", "type": "mechanism", "note": "Low albumin and clotting factors: oedema, ascites and bleeding tendency.", "link": null, "level": 1}, {"id": "n5", "label": "Failed detoxification", "type": "mechanism", "note": "Ammonia and other toxins reach the brain: hepatic encephalopathy.", "link": null, "level": 1}, {"id": "n6", "label": "Stigmata of liver disease", "type": "sign", "note": "Spider naevi, palmar erythema, gynaecomastia, Dupuytren's, leuconychia and loss of body hair.", "link": "signs/sign/cirrhosis-signs", "level": 2}, {"id": "n7", "label": "Jaundice", "type": "sign", "note": "Scleral icterus visible once bilirubin exceeds about 40 micromol/L.", "link": "signs/sign/jaundice", "level": 2}, {"id": "n8", "label": "Oesophageal varices", "type": "diagnosis", "note": "Dilated collaterals at the gastro-oesophageal junction that bleed torrentially.", "link": null, "level": 2}, {"id": "n9", "label": "Splenomegaly", "type": "sign", "note": "Congestive enlargement; palpable spleen is always abnormal.", "link": "signs/sign/spleen-palp", "level": 2}, {"id": "n10", "label": "Ascites", "type": "sign", "note": "Shifting dullness (LR about 2) and fluid wave; the puddle sign for small volumes.", "link": "signs/sign/shifting-dullness", "level": 2}, {"id": "n11", "label": "Caput medusae", "type": "sign", "note": "Dilated periumbilical veins draining away from the umbilicus through the recanalised umbilical vein.", "link": null, "level": 2}, {"id": "n12", "label": "Asterixis", "type": "sign", "note": "Flapping tremor of the outstretched hands: hepatic encephalopathy (also CO2 retention and uraemia).", "link": "signs/sign/asterixis", "level": 2}, {"id": "n13", "label": "Upper GI bleed", "type": "diagnosis", "note": "Haematemesis or melaena; varices, ulcers and Mallory-Weiss tears are the main sources in liver disease.", "link": null, "level": 3}, {"id": "n14", "label": "Haemodynamic assessment", "type": "sign", "note": "Postural pulse rise of 30 or more, shock index over 0.9 and delayed capillary refill reveal large blood loss before the BP falls.", "link": "signs/sign/postural", "level": 4}, {"id": "n15", "label": "Digital rectal examination", "type": "test", "note": "Melaena confirms upper GI bleeding; fresh blood with haemodynamic compromise can still be a brisk upper source.", "link": "signs/sign/dre", "level": 4}, {"id": "n16", "label": "Conjunctival pallor", "type": "sign", "note": "Suggests haemoglobin at or below 9 g/dL; the initial Hb lags behind acute loss.", "link": "signs/sign/conj-pallor", "level": 4}, {"id": "n17", "label": "Liver size", "type": "sign", "note": "Small, hard liver in cirrhosis; a smooth enlarged liver in fatty change, congestion or early alcoholic disease.", "link": "signs/sign/liver-palp", "level": 2}, {"id": "n18", "label": "Resuscitate and endoscope", "type": "decision", "note": "Blood products, terlipressin and antibiotics for a suspected variceal bleed; endoscopy within 24 hours, urgently if unstable.", "link": null, "level": 4}], "edges": [{"from": "n1", "to": "n2", "label": "causes"}, {"from": "n1", "to": "n3", "label": "causes"}, {"from": "n1", "to": "n4", "label": "causes"}, {"from": "n1", "to": "n5", "label": "causes"}, {"from": "n2", "to": "n6", "label": "produces"}, {"from": "n1", "to": "n7", "label": "produces"}, {"from": "n3", "to": "n8", "label": "collaterals"}, {"from": "n3", "to": "n9", "label": "congests"}, {"from": "n3", "to": "n10", "label": "with"}, {"from": "n4", "to": "n10", "label": "low albumin"}, {"from": "n3", "to": "n11", "label": "collaterals"}, {"from": "n5", "to": "n12", "label": "produces"}, {"from": "n8", "to": "n13", "label": "bleeds"}, {"from": "n4", "to": "n13", "label": "worsens"}, {"from": "n13", "to": "n14", "label": "assess"}, {"from": "n13", "to": "n15", "label": "confirm"}, {"from": "n13", "to": "n16", "label": "later"}, {"from": "n1", "to": "n17", "label": "alters"}, {"from": "n13", "to": "n5", "label": "precipitates"}, {"from": "n14", "to": "n18", "label": "guides"}], "quiz": [{"q": "Which mechanism produces spider naevi and gynaecomastia in cirrhosis?", "a": "Reduced hepatic clearance of oestrogens."}, {"q": "Name three consequences of portal hypertension you can find on examination.", "a": "Splenomegaly, ascites and caput medusae (varices are seen at endoscopy)."}, {"q": "Which bedside measures reveal large acute blood loss before the blood pressure falls?", "a": "Postural pulse increment of 30 or more (or severe postural dizziness), shock index above 0.9 and delayed capillary refill."}]}, {"id": "headache-red-flags", "title": "Headache: SNOOP to the dangerous causes", "sys": "neuro", "intro": "Most headaches are primary, but five secondary causes kill or blind if missed: subarachnoid haemorrhage, meningitis, giant cell arteritis, raised intracranial pressure and carbon monoxide poisoning. The map links each SNOOP red flag and bedside sign to the diagnosis it should trigger.", "nodes": [{"id": "n1", "label": "Headache", "type": "symptom", "note": "Ask onset to peak, first or worst, pattern change, position, Valsalva, visual symptoms, jaw claudication, fever, rash and exposure.", "link": "learn/pres/head", "level": 0}, {"id": "n2", "label": "Systemic features", "type": "history", "note": "Fever, rash, weight loss, cancer, HIV, pregnancy or anticoagulants mark a secondary cause.", "link": null, "level": 1}, {"id": "n3", "label": "Neurological signs", "type": "history", "note": "Any focal deficit, confusion or papilloedema (LR about 5 for a serious cause).", "link": null, "level": 1}, {"id": "n4", "label": "Onset sudden", "type": "history", "note": "Thunderclap: maximal within one minute, SAH until proven otherwise.", "link": null, "level": 1}, {"id": "n5", "label": "Older than 50", "type": "history", "note": "New headache after 50 raises GCA and tumour.", "link": null, "level": 1}, {"id": "n6", "label": "Pattern or positional", "type": "history", "note": "Change from usual headaches; worse lying flat or on waking (raised ICP), worse with Valsalva.", "link": null, "level": 1}, {"id": "n7", "label": "Subarachnoid haemorrhage", "type": "diagnosis", "note": "Ruptured aneurysm: thunderclap, vomiting, neck stiffness, sometimes collapse; CT within 6 hours is near-definitive.", "link": null, "level": 2}, {"id": "n8", "label": "Meningitis", "type": "diagnosis", "note": "Fever, headache, neck stiffness and altered consciousness; a non-blanching rash means meningococcal sepsis.", "link": "practice/hdpe/mening", "level": 2}, {"id": "n9", "label": "Giant cell arteritis", "type": "diagnosis", "note": "Granulomatous arteritis in those over 50: jaw claudication (LR about 4), scalp tenderness, visual loss; start steroids before biopsy.", "link": null, "level": 2}, {"id": "n10", "label": "Raised intracranial pressure", "type": "diagnosis", "note": "Tumour, venous sinus thrombosis, idiopathic intracranial hypertension or hydrocephalus; worse lying, morning vomiting, papilloedema.", "link": null, "level": 2}, {"id": "n11", "label": "Carbon monoxide", "type": "diagnosis", "note": "Headache, nausea and confusion in several household members, worse indoors in winter; pulse oximetry reads falsely normal.", "link": null, "level": 2}, {"id": "n12", "label": "Nuchal rigidity", "type": "sign", "note": "Resistance to passive neck flexion; Kernig's and Brudzinski's signs are specific but insensitive.", "link": "signs/sign/neck-stiffness", "level": 3}, {"id": "n13", "label": "Non-blanching rash", "type": "sign", "note": "Petechiae or purpura that persist under a glass: meningococcal disease, give antibiotics immediately.", "link": "signs/sign/purpura-glass", "level": 3}, {"id": "n14", "label": "Papilloedema", "type": "sign", "note": "Blurred disc margins and loss of venous pulsation on fundoscopy; takes hours to days to develop.", "link": "signs/sign/fundoscopy", "level": 3}, {"id": "n15", "label": "Temporal artery findings", "type": "sign", "note": "Tender, thickened or pulseless temporal artery; absent pulse has LR about 3 for GCA.", "link": null, "level": 3}, {"id": "n16", "label": "CT then lumbar puncture", "type": "test", "note": "Non-contrast CT within 6 hours of onset detects almost all SAH; otherwise CT plus LP at 12 hours for xanthochromia.", "link": null, "level": 4}, {"id": "n17", "label": "Migraine", "type": "diagnosis", "note": "Pulsating, unilateral, nausea, disabling (POUND, LR about 3.5 when 3 or more present); aura marches over minutes.", "link": null, "level": 2}, {"id": "n18", "label": "Angle-closure glaucoma", "type": "diagnosis", "note": "Painful red eye, hazy cornea, fixed mid-dilated pupil and vomiting; an eye emergency that presents as headache.", "link": "signs/sign/red-eye", "level": 2}], "edges": [{"from": "n1", "to": "n2", "label": "S"}, {"from": "n1", "to": "n3", "label": "N"}, {"from": "n1", "to": "n4", "label": "O"}, {"from": "n1", "to": "n5", "label": "O"}, {"from": "n1", "to": "n6", "label": "P"}, {"from": "n4", "to": "n7", "label": "suggests"}, {"from": "n2", "to": "n8", "label": "fever"}, {"from": "n5", "to": "n9", "label": "suggests"}, {"from": "n6", "to": "n10", "label": "suggests"}, {"from": "n3", "to": "n10", "label": "suggests"}, {"from": "n2", "to": "n11", "label": "household"}, {"from": "n7", "to": "n12", "label": "causes"}, {"from": "n8", "to": "n12", "label": "causes"}, {"from": "n8", "to": "n13", "label": "meningococcal"}, {"from": "n10", "to": "n14", "label": "causes"}, {"from": "n9", "to": "n15", "label": "causes"}, {"from": "n7", "to": "n16", "label": "confirm"}, {"from": "n1", "to": "n17", "label": "if no flags"}, {"from": "n1", "to": "n18", "label": "red eye"}], "quiz": [{"q": "What is a thunderclap headache and what must it be treated as?", "a": "Headache maximal within one minute of onset; subarachnoid haemorrhage until proven otherwise."}, {"q": "Which historical feature has the strongest LR for giant cell arteritis?", "a": "Jaw claudication (LR about 4) in a patient over 50 with new headache."}, {"q": "Why can carbon monoxide poisoning be missed on a standard pulse oximeter?", "a": "Carboxyhaemoglobin is read as oxyhaemoglobin, so saturation appears normal."}]}, {"id": "stroke-localisation", "title": "Stroke: cortex, capsule or brainstem?", "sys": "neuro", "intro": "The pattern of deficit tells you where the stroke is and which artery is blocked, which decides whether thrombectomy is on the table. The map links cortical signs, pure motor lacunes and crossed brainstem findings to their anatomy and to the BE-FAST and LVO screens.", "nodes": [{"id": "n1", "label": "Sudden focal deficit", "type": "symptom", "note": "Stroke until proven otherwise; note the exact time last seen well.", "link": "signs/sign/befast", "level": 0}, {"id": "n2", "label": "BE-FAST", "type": "test", "note": "Balance, Eyes, Face, Arm, Speech, Time: adding balance and vision catches posterior circulation strokes that FAST misses.", "link": "practice/hdpe/stroke", "level": 1}, {"id": "n3", "label": "Cortex", "type": "anatomy", "note": "Middle cerebral artery territory: face and arm weaker than leg, plus the cortical signs that localise to the surface.", "link": null, "level": 1}, {"id": "n4", "label": "Internal capsule", "type": "anatomy", "note": "Lacunar infarct of a small perforating artery: pure motor or pure sensory deficit, face, arm and leg equally, no cortical signs.", "link": "practice/localiser/lacune", "level": 1}, {"id": "n5", "label": "Brainstem", "type": "anatomy", "note": "Crossed signs: cranial nerve on one side, body on the other, with vertigo, diplopia, dysarthria or dysphagia.", "link": null, "level": 1}, {"id": "n6", "label": "Anterior cerebral", "type": "anatomy", "note": "Leg weaker than arm, with abulia and urinary incontinence.", "link": "practice/localiser/aca", "level": 1}, {"id": "n7", "label": "Aphasia", "type": "sign", "note": "Dominant hemisphere: Broca's (non-fluent, frontal) or Wernicke's (fluent nonsense, temporal).", "link": "practice/localiser/broca", "level": 2}, {"id": "n8", "label": "Neglect", "type": "sign", "note": "Non-dominant parietal: ignores the left side of space and body, may deny the deficit.", "link": "practice/localiser/neglect", "level": 2}, {"id": "n9", "label": "Gaze deviation", "type": "sign", "note": "Eyes look toward the cortical lesion (frontal eye field) and away from the weak side.", "link": null, "level": 2}, {"id": "n10", "label": "Hemianopia", "type": "sign", "note": "Homonymous field loss from optic radiation or occipital involvement.", "link": "signs/sign/visual-fields", "level": 2}, {"id": "n11", "label": "Pure motor hemiparesis", "type": "sign", "note": "Face, arm and leg equally weak with no sensory, visual or language deficit.", "link": "practice/localiser/lacune", "level": 2}, {"id": "n12", "label": "Crossed signs", "type": "sign", "note": "Ipsilateral cranial nerve palsy with contralateral limb weakness or numbness, as in Weber or Millard-Gubler syndromes.", "link": "practice/localiser/millard", "level": 2}, {"id": "n13", "label": "Lateral medullary", "type": "sign", "note": "Wallenberg: vertigo, ipsilateral Horner's and facial numbness, contralateral body numbness, hoarseness.", "link": "practice/localiser/wallenberg", "level": 2}, {"id": "n14", "label": "Forehead-sparing facial weakness", "type": "sign", "note": "Upper motor neuron facial weakness spares the forehead; whole-face weakness is a peripheral nerve lesion.", "link": "signs/sign/facial-palsy", "level": 2}, {"id": "n15", "label": "Pronator drift", "type": "sign", "note": "Subtle corticospinal weakness: the arm pronates and drifts downward with eyes closed.", "link": "signs/sign/pronator-drift", "level": 2}, {"id": "n16", "label": "Large vessel occlusion", "type": "decision", "note": "Cortical signs (gaze deviation, aphasia, neglect) with hemiparesis predict a proximal occlusion amenable to thrombectomy up to 24 hours.", "link": null, "level": 3}, {"id": "n17", "label": "CT and CT angiography", "type": "test", "note": "Non-contrast CT excludes haemorrhage; CTA finds the occlusion; perfusion imaging selects late-window patients.", "link": null, "level": 3}, {"id": "n18", "label": "Swallow screen", "type": "test", "note": "Bedside water swallow test before any oral intake to prevent aspiration.", "link": "signs/sign/water-swallow", "level": 3}], "edges": [{"from": "n1", "to": "n2", "label": "screen"}, {"from": "n1", "to": "n3", "label": "face and arm"}, {"from": "n1", "to": "n4", "label": "all equal"}, {"from": "n1", "to": "n5", "label": "crossed"}, {"from": "n1", "to": "n6", "label": "leg"}, {"from": "n3", "to": "n7", "label": "dominant"}, {"from": "n3", "to": "n8", "label": "non-dominant"}, {"from": "n3", "to": "n9", "label": "frontal"}, {"from": "n3", "to": "n10", "label": "posterior"}, {"from": "n4", "to": "n11", "label": "produces"}, {"from": "n5", "to": "n12", "label": "produces"}, {"from": "n5", "to": "n13", "label": "medulla"}, {"from": "n3", "to": "n14", "label": "UMN"}, {"from": "n4", "to": "n14", "label": "UMN"}, {"from": "n3", "to": "n15", "label": "subtle"}, {"from": "n7", "to": "n16", "label": "predicts"}, {"from": "n8", "to": "n16", "label": "predicts"}, {"from": "n9", "to": "n16", "label": "predicts"}, {"from": "n16", "to": "n17", "label": "needs"}, {"from": "n1", "to": "n18", "label": "before oral"}], "quiz": [{"q": "Which deficits point to a cortical rather than a capsular stroke?", "a": "Aphasia, neglect, gaze deviation and hemianopia; a capsular lacune gives pure motor or sensory loss without them."}, {"q": "What does BE-FAST add to FAST and why?", "a": "Balance and Eyes, to catch posterior circulation strokes presenting with ataxia, vertigo or visual loss."}, {"q": "Why does forehead sparing matter in facial weakness?", "a": "The forehead receives bilateral cortical input, so sparing indicates an upper motor neuron (central) lesion rather than a facial nerve palsy."}]}, {"id": "vertigo", "title": "Vertigo: HINTS and Dix-Hallpike decide central from peripheral", "sys": "neuro", "intro": "Continuous vertigo with nystagmus is the acute vestibular syndrome, where HINTS outperforms early MRI for stroke; episodic positional vertigo is BPPV, diagnosed and treated at the bedside. The map sorts dizziness by timing and trigger and shows what each test result means.", "nodes": [{"id": "n1", "label": "Dizziness", "type": "symptom", "note": "Ask timing and triggers rather than 'what kind': continuous or episodic, spontaneous or positional, with hearing change or neurological symptoms.", "link": "learn/pres/dizz", "level": 0}, {"id": "n2", "label": "Acute vestibular syndrome", "type": "mechanism", "note": "Continuous vertigo, nausea, nystagmus and gait unsteadiness for more than 24 hours: vestibular neuritis or posterior circulation stroke.", "link": "practice/hdpe/vert", "level": 1}, {"id": "n3", "label": "Episodic positional", "type": "mechanism", "note": "Seconds of vertigo on turning in bed or looking up: displaced otoconia in a semicircular canal.", "link": null, "level": 1}, {"id": "n4", "label": "Episodic spontaneous", "type": "mechanism", "note": "Minutes to hours, unprovoked: Meniere's (with hearing loss and tinnitus), vestibular migraine or TIA.", "link": null, "level": 1}, {"id": "n5", "label": "HINTS", "type": "test", "note": "Head Impulse, Nystagmus, Test of Skew: performed only in a patient with ongoing nystagmus; more sensitive than early MRI for stroke.", "link": "signs/sign/hints", "level": 2}, {"id": "n6", "label": "Head impulse", "type": "test", "note": "A corrective saccade after a rapid head turn shows a peripheral deficit; a normal (no saccade) response in acute vertigo is worrying for stroke.", "link": null, "level": 3}, {"id": "n7", "label": "Nystagmus", "type": "test", "note": "Unidirectional horizontal nystagmus is peripheral; direction-changing, vertical or torsional nystagmus is central.", "link": null, "level": 3}, {"id": "n8", "label": "Test of skew", "type": "test", "note": "Vertical ocular misalignment on alternate cover testing is a brainstem sign.", "link": null, "level": 3}, {"id": "n9", "label": "Vestibular neuritis", "type": "diagnosis", "note": "Peripheral: abnormal head impulse, unidirectional nystagmus, no skew; can walk unaided.", "link": null, "level": 4}, {"id": "n10", "label": "Posterior circulation stroke", "type": "diagnosis", "note": "Central: any one of normal head impulse, direction-changing nystagmus or skew; cerebellar or lateral medullary infarct.", "link": "practice/localiser/wallenberg", "level": 4}, {"id": "n11", "label": "Dix-Hallpike", "type": "test", "note": "Head turned 45 degrees, laid back quickly with the head extended: torsional upbeat nystagmus after a few seconds' latency, fatiguing, for posterior canal BPPV.", "link": "signs/sign/dix-hallpike", "level": 2}, {"id": "n12", "label": "BPPV", "type": "diagnosis", "note": "Benign paroxysmal positional vertigo: posterior canal in most cases; no hearing loss and normal neurology.", "link": null, "level": 3}, {"id": "n13", "label": "Epley manoeuvre", "type": "decision", "note": "Repositioning cures most posterior canal BPPV at the first attempt.", "link": "signs/sign/epley", "level": 4}, {"id": "n14", "label": "Gait and cerebellar signs", "type": "sign", "note": "Inability to stand unaided, truncal ataxia, limb dysmetria or dysarthria point to a central cause.", "link": "signs/sign/tandem", "level": 2}, {"id": "n15", "label": "Hearing loss", "type": "sign", "note": "Acute unilateral hearing loss with vertigo: labyrinthitis, Meniere's or AICA infarct; check Rinne and Weber.", "link": "signs/sign/rinne-weber", "level": 2}, {"id": "n16", "label": "Presyncope", "type": "mechanism", "note": "Light-headedness from reduced cerebral perfusion: arrhythmia, orthostatic hypotension, bleeding. Check postural observations.", "link": "signs/sign/postural", "level": 1}, {"id": "n17", "label": "MRI with diffusion", "type": "test", "note": "Needed when HINTS is central or the examiner is unsure; early MRI misses up to a fifth of posterior strokes within 48 hours.", "link": null, "level": 4}], "edges": [{"from": "n1", "to": "n2", "label": "continuous"}, {"from": "n1", "to": "n3", "label": "positional"}, {"from": "n1", "to": "n4", "label": "episodic"}, {"from": "n1", "to": "n16", "label": "light-headed"}, {"from": "n2", "to": "n5", "label": "apply"}, {"from": "n5", "to": "n6", "label": "H"}, {"from": "n5", "to": "n7", "label": "N"}, {"from": "n5", "to": "n8", "label": "S"}, {"from": "n6", "to": "n9", "label": "saccade"}, {"from": "n7", "to": "n9", "label": "unidirectional"}, {"from": "n6", "to": "n10", "label": "normal"}, {"from": "n7", "to": "n10", "label": "changes"}, {"from": "n8", "to": "n10", "label": "present"}, {"from": "n3", "to": "n11", "label": "apply"}, {"from": "n11", "to": "n12", "label": "positive"}, {"from": "n12", "to": "n13", "label": "treat"}, {"from": "n2", "to": "n14", "label": "check"}, {"from": "n14", "to": "n10", "label": "supports"}, {"from": "n2", "to": "n15", "label": "check"}, {"from": "n10", "to": "n17", "label": "confirm"}], "quiz": [{"q": "In acute vestibular syndrome, which head impulse result is reassuring and which is worrying?", "a": "A corrective saccade (abnormal) is reassuring for a peripheral cause; a normal head impulse without saccade suggests stroke."}, {"q": "When should HINTS not be used?", "a": "When the patient has no ongoing nystagmus or vertigo at the time of examination (it is for the acute vestibular syndrome only)."}, {"q": "Describe the nystagmus of a positive Dix-Hallpike for posterior canal BPPV.", "a": "Torsional upbeat nystagmus after a latency of a few seconds, lasting under a minute and fatiguing on repetition."}]}, {"id": "weakness-localisation", "title": "Weakness: UMN or LMN, then where along the pathway", "sys": "neuro", "intro": "Tone, reflexes, plantars and the distribution of weakness place a lesion in the cortex, cord, root, nerve, neuromuscular junction or muscle. The map pairs each level with its signature findings and a case to practise on.", "nodes": [{"id": "n1", "label": "Weakness", "type": "symptom", "note": "Distribution (one side, both legs, proximal, distal), onset, fatigability, sensory level, bladder.", "link": null, "level": 0}, {"id": "n2", "label": "Upper motor neuron", "type": "mechanism", "note": "Corticospinal lesion: spastic tone, brisk reflexes, clonus, extensor plantar, pyramidal pattern (arm extensors, leg flexors weak).", "link": null, "level": 1}, {"id": "n3", "label": "Lower motor neuron", "type": "mechanism", "note": "Anterior horn cell, root or nerve: flaccid tone, wasting, fasciculation, reduced or absent reflexes, flexor plantars.", "link": null, "level": 1}, {"id": "n4", "label": "Neuromuscular junction", "type": "mechanism", "note": "Fatigable weakness, normal reflexes and sensation, ocular and bulbar muscles first.", "link": null, "level": 1}, {"id": "n5", "label": "Muscle", "type": "mechanism", "note": "Symmetrical proximal weakness, preserved reflexes until late, no sensory loss.", "link": null, "level": 1}, {"id": "n6", "label": "Babinski and Hoffmann", "type": "sign", "note": "Extensor plantar and Hoffmann's sign are release signs of corticospinal damage.", "link": "signs/sign/babinski", "level": 2}, {"id": "n7", "label": "Hyperreflexia and clonus", "type": "sign", "note": "More than three beats of ankle clonus is pathological; reflexes brisk and spreading.", "link": "signs/sign/clonus", "level": 2}, {"id": "n8", "label": "Wasting and fasciculation", "type": "sign", "note": "Denervated muscle shrinks and twitches; fasciculation at rest is a lower motor neuron sign.", "link": null, "level": 2}, {"id": "n9", "label": "Hemisphere", "type": "anatomy", "note": "Contralateral face, arm and leg; cortical signs if the surface is involved.", "link": "practice/localiser/lacune", "level": 3}, {"id": "n10", "label": "Spinal cord", "type": "anatomy", "note": "Bilateral UMN signs below the lesion with a sensory level and bladder involvement; LMN at the level itself.", "link": "practice/localiser/mscc", "level": 3}, {"id": "n11", "label": "Brown-Sequard", "type": "anatomy", "note": "Hemicord: ipsilateral weakness and proprioception loss, contralateral pain and temperature loss.", "link": "practice/localiser/brownsequard", "level": 4}, {"id": "n12", "label": "Nerve root", "type": "anatomy", "note": "Dermatomal pain and numbness, myotomal weakness, one reflex lost (L5 foot drop, S1 ankle jerk).", "link": "practice/localiser/l5", "level": 3}, {"id": "n13", "label": "Peripheral nerve", "type": "anatomy", "note": "Weakness and sensory loss in one nerve's territory (common peroneal foot drop) or length-dependent glove-and-stocking (neuropathy).", "link": "practice/localiser/peroneal", "level": 3}, {"id": "n14", "label": "Guillain-Barre", "type": "diagnosis", "note": "Ascending areflexic weakness over days after an infection; watch vital capacity and bulbar function.", "link": "practice/localiser/gbs", "level": 4}, {"id": "n15", "label": "Myasthenia gravis", "type": "diagnosis", "note": "Ptosis and diplopia worse by evening; the ice pack test improves ptosis.", "link": "signs/sign/ice-pack", "level": 2}, {"id": "n16", "label": "Myopathy", "type": "diagnosis", "note": "Cannot rise from a chair or lift the arms; proximal, symmetrical, often with raised CK.", "link": "practice/localiser/myopathy", "level": 2}, {"id": "n17", "label": "Deep tendon reflexes", "type": "test", "note": "Brisk with UMN, absent with LMN and neuropathy, normal in NMJ and early myopathy: the single most useful discriminator.", "link": "signs/sign/reflexes", "level": 2}, {"id": "n18", "label": "Functional weakness", "type": "diagnosis", "note": "Hoover's sign: involuntary hip extension returns when the other leg flexes against resistance.", "link": "signs/sign/hoover-functional", "level": 2}, {"id": "n19", "label": "Cauda equina", "type": "diagnosis", "note": "Bilateral root compression: saddle anaesthesia, reduced anal tone, retention; an emergency.", "link": "practice/localiser/cauda", "level": 4}], "edges": [{"from": "n1", "to": "n2", "label": "spastic, brisk"}, {"from": "n1", "to": "n3", "label": "flaccid, absent"}, {"from": "n1", "to": "n4", "label": "fatigable"}, {"from": "n1", "to": "n5", "label": "proximal"}, {"from": "n1", "to": "n18", "label": "inconsistent"}, {"from": "n2", "to": "n6", "label": "sign"}, {"from": "n2", "to": "n7", "label": "sign"}, {"from": "n3", "to": "n8", "label": "sign"}, {"from": "n1", "to": "n17", "label": "test first"}, {"from": "n2", "to": "n9", "label": "one side"}, {"from": "n2", "to": "n10", "label": "both legs"}, {"from": "n10", "to": "n11", "label": "hemicord"}, {"from": "n3", "to": "n12", "label": "dermatomal"}, {"from": "n3", "to": "n13", "label": "nerve territory"}, {"from": "n13", "to": "n14", "label": "ascending"}, {"from": "n12", "to": "n19", "label": "bilateral"}, {"from": "n4", "to": "n15", "label": "diagnosis"}, {"from": "n5", "to": "n16", "label": "diagnosis"}], "quiz": [{"q": "List the four findings that distinguish an upper from a lower motor neuron lesion.", "a": "UMN: increased tone, brisk reflexes, extensor plantar, no wasting. LMN: reduced tone, absent reflexes, flexor plantar, wasting and fasciculation."}, {"q": "What combination of signs points to a spinal cord lesion?", "a": "Bilateral UMN signs below a sensory level with bladder involvement (and LMN signs at the level)."}, {"q": "How does the ice pack test help in suspected myasthenia?", "a": "Cooling the eyelid for two minutes improves ptosis by slowing acetylcholinesterase."}]}, {"id": "back-pain", "title": "Back pain: mechanical pattern or a red flag diagnosis?", "sys": "msk", "intro": "Most low back pain is mechanical and needs reassurance and movement, but cauda equina, spinal infection, fracture and malignancy must be excluded by targeted questions and a focused neurological examination. The map shows which features point to each and which tests follow.", "nodes": [{"id": "n1", "label": "Low back pain", "type": "symptom", "note": "Ask pattern, radiation below the knee, bilateral symptoms, saddle numbness, bladder and bowel change, and the red flag list.", "link": "learn/pres/back", "level": 0}, {"id": "n2", "label": "Mechanical pain", "type": "mechanism", "note": "Worse with activity and certain positions, better with rest, no systemic features; includes disc, facet and muscular pain.", "link": null, "level": 1}, {"id": "n3", "label": "Radicular pain", "type": "mechanism", "note": "Nerve root irritation by a disc: sharp leg pain below the knee in a dermatome, with numbness or weakness.", "link": "practice/localiser/l5", "level": 1}, {"id": "n4", "label": "Inflammatory pattern", "type": "mechanism", "note": "Morning stiffness over 30 minutes, better with exercise, night pain, age under 40: axial spondyloarthritis.", "link": null, "level": 1}, {"id": "n5", "label": "Red flags", "type": "history", "note": "Age under 20 or over 50, cancer, weight loss, fever, IV drug use, immunosuppression, steroids, trauma, night pain, progressive neurology.", "link": null, "level": 1}, {"id": "n6", "label": "Cauda equina", "type": "diagnosis", "note": "Compression of the sacral roots: bilateral sciatica, saddle numbness, painless retention, loss of anal tone; emergency MRI and decompression.", "link": "practice/localiser/cauda", "level": 2}, {"id": "n7", "label": "Spinal infection", "type": "diagnosis", "note": "Discitis or epidural abscess: fever, IV drug use, recent bacteraemia or surgery, unrelenting pain, raised CRP.", "link": null, "level": 2}, {"id": "n8", "label": "Vertebral fracture", "type": "diagnosis", "note": "Osteoporosis, steroids, older age or significant trauma; focal tenderness over the spinous process.", "link": null, "level": 2}, {"id": "n9", "label": "Spinal malignancy", "type": "diagnosis", "note": "History of cancer has LR about 15; weight loss, age over 50 and failure to improve after a month add to it.", "link": "practice/localiser/mscc", "level": 2}, {"id": "n10", "label": "Straight leg raise", "type": "test", "note": "Leg pain between 30 and 70 degrees reproduces root tension; sensitive but not specific for disc herniation.", "link": "signs/sign/slr", "level": 2}, {"id": "n11", "label": "Crossed straight leg raise", "type": "test", "note": "Pain in the symptomatic leg when the other leg is raised; specific for disc herniation.", "link": "signs/sign/crossed-slr", "level": 2}, {"id": "n12", "label": "Lumbar root screen", "type": "test", "note": "L4 knee jerk and dorsiflexion, L5 great toe extension, S1 ankle jerk and plantarflexion.", "link": "signs/sign/lumbar-roots", "level": 2}, {"id": "n13", "label": "Saddle sensation and anal tone", "type": "sign", "note": "Test perianal pinprick and anal tone, and measure a post-void residual: the examination for cauda equina.", "link": "signs/sign/cauda", "level": 3}, {"id": "n14", "label": "Schober's test", "type": "test", "note": "Lumbar flexion under 5 cm (modified Schober) suggests spondyloarthritis.", "link": "signs/sign/schober", "level": 2}, {"id": "n15", "label": "Waddell signs", "type": "sign", "note": "Non-organic signs (superficial tenderness, simulation, distraction) reflect distress, not malingering, and predict poor response to surgery.", "link": "signs/sign/waddell", "level": 2}, {"id": "n16", "label": "Yellow flags", "type": "history", "note": "Fear of movement, low mood, belief that pain means damage, job dissatisfaction and compensation predict chronicity.", "link": null, "level": 2}, {"id": "n17", "label": "MRI", "type": "test", "note": "Urgent for suspected cauda equina, infection or cord compression; not needed for mechanical pain without red flags.", "link": null, "level": 3}, {"id": "n18", "label": "Keep moving", "type": "decision", "note": "Mechanical back pain without red flags: analgesia, stay active, early return to adjusted work.", "link": null, "level": 3}], "edges": [{"from": "n1", "to": "n2", "label": "most"}, {"from": "n1", "to": "n3", "label": "leg pain"}, {"from": "n1", "to": "n4", "label": "stiffness"}, {"from": "n1", "to": "n5", "label": "screen"}, {"from": "n5", "to": "n6", "label": "neurology"}, {"from": "n5", "to": "n7", "label": "fever, IVDU"}, {"from": "n5", "to": "n8", "label": "trauma, steroids"}, {"from": "n5", "to": "n9", "label": "cancer, weight"}, {"from": "n3", "to": "n10", "label": "test"}, {"from": "n3", "to": "n11", "label": "test"}, {"from": "n3", "to": "n12", "label": "test"}, {"from": "n6", "to": "n13", "label": "examine"}, {"from": "n3", "to": "n6", "label": "if bilateral"}, {"from": "n4", "to": "n14", "label": "test"}, {"from": "n2", "to": "n15", "label": "assess"}, {"from": "n2", "to": "n16", "label": "assess"}, {"from": "n6", "to": "n17", "label": "urgent"}, {"from": "n7", "to": "n17", "label": "urgent"}, {"from": "n9", "to": "n17", "label": "urgent"}, {"from": "n2", "to": "n18", "label": "manage"}, {"from": "n16", "to": "n18", "label": "address"}], "quiz": [{"q": "Which four features define cauda equina syndrome?", "a": "Bilateral sciatica or leg weakness, saddle anaesthesia, bladder dysfunction (retention or incontinence) and reduced anal tone."}, {"q": "Which historical item has the highest LR for spinal malignancy?", "a": "A history of cancer (LR about 15)."}, {"q": "How does the crossed straight leg raise differ from the straight leg raise in usefulness?", "a": "SLR is sensitive but not specific; crossed SLR is specific but insensitive for disc herniation."}]}, {"id": "knee-injury", "title": "Knee injury: mechanism tells you the structure, the test confirms it", "sys": "msk", "intro": "The way the knee was injured predicts which structure tore: a twist with a pop is the ACL, a valgus blow is the MCL, a dashboard impact the PCL, and a twist with later locking the meniscus. The map links mechanism to structure to the test with the best accuracy and to the Ottawa rule for imaging.", "nodes": [{"id": "n1", "label": "Acute knee injury", "type": "symptom", "note": "Mechanism, pop, timing of swelling (minutes: haemarthrosis; hours: effusion), locking, giving way, ability to weight bear.", "link": "learn/region/knee", "level": 0}, {"id": "n2", "label": "Twist with a pop", "type": "history", "note": "Non-contact pivot with immediate swelling: anterior cruciate ligament.", "link": null, "level": 1}, {"id": "n3", "label": "Valgus force", "type": "history", "note": "Blow to the lateral knee opening the medial side: medial collateral ligament.", "link": null, "level": 1}, {"id": "n4", "label": "Dashboard injury", "type": "history", "note": "Posterior force on the flexed tibia: posterior cruciate ligament.", "link": null, "level": 1}, {"id": "n5", "label": "Twist with later locking", "type": "history", "note": "Rotation on a loaded knee with delayed swelling, catching or locking: meniscal tear.", "link": null, "level": 1}, {"id": "n6", "label": "Fall onto the patella", "type": "history", "note": "Direct blow or forced flexion: fracture or patellar dislocation.", "link": null, "level": 1}, {"id": "n7", "label": "ACL tear", "type": "diagnosis", "note": "Haemarthrosis within hours; instability on pivoting.", "link": "practice/hdpe/acl", "level": 2}, {"id": "n8", "label": "MCL tear", "type": "diagnosis", "note": "Medial tenderness and laxity on valgus stress at 30 degrees.", "link": null, "level": 2}, {"id": "n9", "label": "PCL tear", "type": "diagnosis", "note": "Posterior sag and positive posterior drawer.", "link": null, "level": 2}, {"id": "n10", "label": "Meniscal tear", "type": "diagnosis", "note": "Joint-line tenderness with positive Thessaly or McMurray.", "link": null, "level": 2}, {"id": "n11", "label": "Patellar dislocation", "type": "diagnosis", "note": "Lateral dislocation after a twist; apprehension on lateral patellar glide.", "link": null, "level": 2}, {"id": "n12", "label": "Lachman test", "type": "test", "note": "Anterior translation at 20 to 30 degrees of flexion with a soft endpoint; the most accurate bedside ACL test (LR about 42 if positive).", "link": "signs/sign/lachman", "level": 3}, {"id": "n13", "label": "Pivot shift", "type": "test", "note": "Subluxation and reduction during flexion with valgus and internal rotation; highly specific, hard to do awake.", "link": "signs/sign/pivot-shift", "level": 3}, {"id": "n14", "label": "Valgus and varus stress", "type": "test", "note": "Opening at 30 degrees tests the collateral; opening at 0 degrees means the cruciates are also injured.", "link": "signs/sign/valgus-stress", "level": 3}, {"id": "n15", "label": "Posterior drawer and sag", "type": "test", "note": "Tibia drops back with the knee flexed at 90 degrees; posterior drawer confirms PCL laxity.", "link": "signs/sign/post-drawer", "level": 3}, {"id": "n16", "label": "Thessaly and McMurray", "type": "test", "note": "Thessaly: pain or locking on twisting at 20 degrees of flexion; McMurray: a click on extension with rotation.", "link": "signs/sign/thessaly", "level": 3}, {"id": "n17", "label": "Joint-line tenderness", "type": "sign", "note": "Tenderness along the medial or lateral joint line; sensitive but non-specific for meniscal tear.", "link": "signs/sign/joint-line", "level": 3}, {"id": "n18", "label": "Patellar apprehension", "type": "test", "note": "Fear or quadriceps contraction when the patella is pushed laterally at 30 degrees of flexion.", "link": "signs/sign/patellar-app", "level": 3}, {"id": "n19", "label": "Knee effusion", "type": "sign", "note": "Bulge sign for small effusions, patellar tap for large; haemarthrosis within two hours suggests ACL or fracture.", "link": "signs/sign/knee-effusion", "level": 2}, {"id": "n20", "label": "Ottawa knee rule", "type": "decision", "note": "X-ray if age 55 or over, patellar tenderness, fibular head tenderness, cannot flex to 90 degrees, or cannot weight bear four steps.", "link": "signs/sign/ottawa-knee", "level": 3}], "edges": [{"from": "n1", "to": "n2", "label": "mechanism"}, {"from": "n1", "to": "n3", "label": "mechanism"}, {"from": "n1", "to": "n4", "label": "mechanism"}, {"from": "n1", "to": "n5", "label": "mechanism"}, {"from": "n1", "to": "n6", "label": "mechanism"}, {"from": "n2", "to": "n7", "label": "tears"}, {"from": "n3", "to": "n8", "label": "tears"}, {"from": "n4", "to": "n9", "label": "tears"}, {"from": "n5", "to": "n10", "label": "tears"}, {"from": "n6", "to": "n11", "label": "or fracture"}, {"from": "n7", "to": "n12", "label": "test"}, {"from": "n7", "to": "n13", "label": "test"}, {"from": "n8", "to": "n14", "label": "test"}, {"from": "n9", "to": "n15", "label": "test"}, {"from": "n10", "to": "n16", "label": "test"}, {"from": "n10", "to": "n17", "label": "sign"}, {"from": "n11", "to": "n18", "label": "test"}, {"from": "n1", "to": "n19", "label": "check"}, {"from": "n19", "to": "n7", "label": "early"}, {"from": "n1", "to": "n20", "label": "X-ray?"}, {"from": "n6", "to": "n20", "label": "apply"}], "quiz": [{"q": "Which bedside test is most accurate for an ACL tear?", "a": "The Lachman test (anterior translation with a soft endpoint at 20 to 30 degrees of flexion)."}, {"q": "What does medial opening at full extension, rather than at 30 degrees, tell you?", "a": "The cruciate ligaments are also injured, not just the MCL."}, {"q": "List the Ottawa knee rule criteria.", "a": "Age 55 or over, isolated patellar tenderness, fibular head tenderness, inability to flex to 90 degrees, inability to weight bear four steps immediately and in the department."}]}, {"id": "shoulder-pain", "title": "Shoulder pain: five sources and the tests that sort them", "sys": "msk", "intro": "Shoulder pain comes from the rotator cuff, instability, the acromioclavicular joint, a frozen capsule or somewhere else entirely (neck, diaphragm, heart). The map matches each source to its history and to the examination tests with real diagnostic value.", "nodes": [{"id": "n1", "label": "Shoulder pain", "type": "symptom", "note": "Age, mechanism, night pain, stiffness, instability episodes, neck symptoms and systemic features decide the source.", "link": "learn/region/shoulder", "level": 0}, {"id": "n2", "label": "Rotator cuff", "type": "anatomy", "note": "Supraspinatus, infraspinatus, teres minor and subscapularis: tendinopathy, impingement or tear, usually over 40 or after a fall.", "link": null, "level": 1}, {"id": "n3", "label": "Instability", "type": "anatomy", "note": "Labral and capsular injury after dislocation, usually anterior, in young patients.", "link": null, "level": 1}, {"id": "n4", "label": "Acromioclavicular joint", "type": "anatomy", "note": "Superior pain after a fall on the point of the shoulder or in weightlifters.", "link": null, "level": 1}, {"id": "n5", "label": "Frozen shoulder", "type": "anatomy", "note": "Adhesive capsulitis: global stiffness, worst at night, in the 40 to 60 age group and diabetics.", "link": null, "level": 1}, {"id": "n6", "label": "Referred pain", "type": "anatomy", "note": "Cervical radiculopathy, diaphragmatic irritation, Pancoast tumour or cardiac ischaemia presenting as shoulder pain.", "link": null, "level": 1}, {"id": "n7", "label": "Painful arc", "type": "sign", "note": "Pain between 60 and 120 degrees of abduction as the cuff passes under the acromion.", "link": "signs/sign/painful-arc", "level": 2}, {"id": "n8", "label": "Hawkins-Kennedy and Neer", "type": "test", "note": "Impingement provocation: sensitive but poorly specific; absence of both argues against cuff disease.", "link": "signs/sign/hawkins", "level": 2}, {"id": "n9", "label": "Drop arm and ER lag", "type": "test", "note": "Inability to lower the arm slowly or to hold external rotation: full-thickness supraspinatus or infraspinatus tear.", "link": "signs/sign/drop-arm", "level": 2}, {"id": "n10", "label": "Empty can test", "type": "test", "note": "Weakness or pain with the thumb down at 90 degrees abduction in the scapular plane: supraspinatus.", "link": "signs/sign/empty-can", "level": 2}, {"id": "n11", "label": "Lift-off and belly-press", "type": "test", "note": "Subscapularis: cannot lift the hand off the back or presses with the wrist flexed.", "link": "signs/sign/lift-off", "level": 2}, {"id": "n12", "label": "Apprehension and relocation", "type": "test", "note": "Fear with abduction and external rotation, relieved by posterior pressure on the humeral head: anterior instability.", "link": "signs/sign/apprehension", "level": 2}, {"id": "n13", "label": "Cross-body adduction", "type": "test", "note": "Pain at the AC joint on horizontal adduction; combined with local tenderness.", "link": "signs/sign/cross-body", "level": 2}, {"id": "n14", "label": "Loss of passive external rotation", "type": "sign", "note": "External rotation reduced with the elbow at the side and a firm end-feel: frozen shoulder or glenohumeral arthritis.", "link": "signs/sign/frozen", "level": 2}, {"id": "n15", "label": "Spurling's test", "type": "test", "note": "Neck extension, rotation and axial load reproducing arm pain: cervical root irritation.", "link": "signs/sign/spurling", "level": 2}, {"id": "n16", "label": "Horner's and apical signs", "type": "sign", "note": "Ptosis, miosis and anhidrosis with shoulder pain in a smoker: Pancoast tumour.", "link": "signs/sign/horner", "level": 2}, {"id": "n17", "label": "Speed's test", "type": "test", "note": "Pain in the bicipital groove on resisted forward flexion with the palm up: biceps tendinopathy.", "link": "signs/sign/speed", "level": 2}, {"id": "n18", "label": "Imaging decision", "type": "decision", "note": "X-ray for trauma, deformity or suspected arthritis; ultrasound or MRI for a suspected full-thickness tear in a patient who would have surgery.", "link": null, "level": 3}], "edges": [{"from": "n1", "to": "n2", "label": "source"}, {"from": "n1", "to": "n3", "label": "source"}, {"from": "n1", "to": "n4", "label": "source"}, {"from": "n1", "to": "n5", "label": "source"}, {"from": "n1", "to": "n6", "label": "source"}, {"from": "n2", "to": "n7", "label": "sign"}, {"from": "n2", "to": "n8", "label": "impingement"}, {"from": "n2", "to": "n9", "label": "tear"}, {"from": "n2", "to": "n10", "label": "supraspinatus"}, {"from": "n2", "to": "n11", "label": "subscapularis"}, {"from": "n2", "to": "n17", "label": "biceps"}, {"from": "n3", "to": "n12", "label": "test"}, {"from": "n4", "to": "n13", "label": "test"}, {"from": "n5", "to": "n14", "label": "sign"}, {"from": "n6", "to": "n15", "label": "cervical"}, {"from": "n6", "to": "n16", "label": "Pancoast"}, {"from": "n9", "to": "n18", "label": "if positive"}, {"from": "n14", "to": "n18", "label": "X-ray"}], "quiz": [{"q": "Which two tests best indicate a full-thickness rotator cuff tear?", "a": "The drop arm sign and the external rotation lag sign."}, {"q": "What sign separates frozen shoulder from cuff disease?", "a": "Loss of passive external rotation with the elbow at the side (cuff disease keeps passive range)."}, {"q": "How does the relocation test confirm anterior instability?", "a": "Apprehension in abduction and external rotation is relieved by posterior pressure on the humeral head."}]}, {"id": "sepsis-recognition", "title": "Sepsis: scores, lactate and finding the source", "sys": "gen", "intro": "Sepsis is life-threatening organ dysfunction caused by a dysregulated response to infection, and early recognition depends on physiology (NEWS2, qSOFA), perfusion (lactate, mottling, capillary refill) and a disciplined search for the source. The map links the warning signs to the mechanisms and the actions they trigger.", "nodes": [{"id": "n1", "label": "Suspected infection", "type": "symptom", "note": "Fever or hypothermia, rigors, new confusion, or a known source; immunosuppressed and elderly patients may have none.", "link": "learn/pres/fever", "level": 0}, {"id": "n2", "label": "Sepsis", "type": "diagnosis", "note": "Infection plus organ dysfunction (SOFA rise of 2 or more); septic shock adds vasopressor need and lactate over 2 despite fluid.", "link": null, "level": 1}, {"id": "n3", "label": "Vasodilatation and leak", "type": "mechanism", "note": "Inflammatory mediators dilate vessels and leak capillaries: warm, hypotensive, with relative hypovolaemia.", "link": null, "level": 2}, {"id": "n4", "label": "Tissue hypoperfusion", "type": "mechanism", "note": "Mismatch of oxygen delivery and demand raises lactate and injures kidneys, brain and lungs.", "link": null, "level": 2}, {"id": "n5", "label": "NEWS2", "type": "test", "note": "Aggregate of RR, SpO2, temperature, systolic BP, pulse and consciousness: 5 or more, or 3 in one parameter, triggers urgent review.", "link": "signs/sign/news2", "level": 1}, {"id": "n6", "label": "qSOFA", "type": "test", "note": "RR 22 or more, altered mentation, systolic 100 or less: 2 or more flags high risk, but it is too insensitive to use as a screen alone.", "link": "signs/sign/qsofa", "level": 1}, {"id": "n7", "label": "Respiratory rate", "type": "sign", "note": "The earliest vital sign to change; above 22 to 25 is a red flag in every score.", "link": "signs/sign/resp-rate", "level": 2}, {"id": "n8", "label": "New confusion", "type": "sign", "note": "Encephalopathy from hypoperfusion and cytokines; a red flag that is often dismissed in the elderly.", "link": "signs/sign/gcs", "level": 2}, {"id": "n9", "label": "Lactate", "type": "test", "note": "Over 2 mmol/L shows hypoperfusion; over 4 mandates fluid resuscitation and repeat measurement.", "link": null, "level": 3}, {"id": "n10", "label": "Mottling and cap refill", "type": "sign", "note": "Knee mottling and capillary refill over 3 s mark skin hypoperfusion and predict mortality.", "link": "signs/sign/passive-leg-mottling", "level": 3}, {"id": "n11", "label": "Oliguria", "type": "sign", "note": "Urine output below 0.5 mL/kg/h: renal hypoperfusion.", "link": null, "level": 3}, {"id": "n12", "label": "Chest source", "type": "sign", "note": "Crackles, bronchial breathing, dullness: pneumonia is the commonest source; CURB-65 grades severity.", "link": "signs/sign/curb65", "level": 2}, {"id": "n13", "label": "Urinary source", "type": "sign", "note": "Costovertebral angle tenderness and dysuria: pyelonephritis.", "link": "signs/sign/cva", "level": 2}, {"id": "n14", "label": "Abdominal source", "type": "sign", "note": "Peritonism, Murphy's sign or RLQ tenderness: cholangitis, perforation, appendicitis.", "link": "signs/sign/rebound", "level": 2}, {"id": "n15", "label": "Skin and soft tissue", "type": "sign", "note": "Cellulitis, pain out of proportion with crepitus or rapid spread (necrotising fasciitis), line sites.", "link": "learn/dcond/necfasc", "level": 2}, {"id": "n16", "label": "Non-blanching rash", "type": "sign", "note": "Petechiae or purpura under a glass: meningococcal sepsis, antibiotics immediately.", "link": "signs/sign/purpura-glass", "level": 2}, {"id": "n17", "label": "Endocarditis stigmata", "type": "sign", "note": "New murmur, splinter haemorrhages, Janeway lesions in fever with bacteraemia or injecting drug use.", "link": "signs/sign/endocarditis-stigmata", "level": 2}, {"id": "n18", "label": "Sepsis Six within the hour", "type": "decision", "note": "Oxygen, cultures, antibiotics, fluid bolus, lactate, urine output; escalate for vasopressors if MAP stays below 65.", "link": null, "level": 4}], "edges": [{"from": "n1", "to": "n2", "label": "becomes"}, {"from": "n2", "to": "n3", "label": "mechanism"}, {"from": "n2", "to": "n4", "label": "mechanism"}, {"from": "n1", "to": "n5", "label": "score"}, {"from": "n1", "to": "n6", "label": "score"}, {"from": "n5", "to": "n7", "label": "includes"}, {"from": "n6", "to": "n7", "label": "includes"}, {"from": "n5", "to": "n8", "label": "includes"}, {"from": "n6", "to": "n8", "label": "includes"}, {"from": "n4", "to": "n9", "label": "raises"}, {"from": "n4", "to": "n10", "label": "produces"}, {"from": "n4", "to": "n11", "label": "produces"}, {"from": "n3", "to": "n10", "label": "worsens"}, {"from": "n1", "to": "n12", "label": "source"}, {"from": "n1", "to": "n13", "label": "source"}, {"from": "n1", "to": "n14", "label": "source"}, {"from": "n1", "to": "n15", "label": "source"}, {"from": "n1", "to": "n16", "label": "source"}, {"from": "n1", "to": "n17", "label": "source"}, {"from": "n5", "to": "n18", "label": "triggers"}, {"from": "n9", "to": "n18", "label": "triggers"}, {"from": "n16", "to": "n18", "label": "immediately"}], "quiz": [{"q": "What NEWS2 score triggers an urgent clinical review?", "a": "A total of 5 or more, or a score of 3 in any single parameter."}, {"q": "Why should qSOFA not be used alone to screen for sepsis?", "a": "It is specific but insensitive; many septic patients score below 2 early on."}, {"q": "Which lactate threshold defines septic shock together with vasopressor dependence?", "a": "Lactate above 2 mmol/L despite adequate fluid resuscitation."}]}, {"id": "the-rash-approach", "title": "The rash: primary lesion, distribution, then the emergencies", "sys": "derm", "intro": "Name the primary lesion, describe its distribution and configuration, and the differential nearly writes itself; a few patterns are emergencies that need the glass test, Nikolsky sign or immediate antibiotics. The map builds that approach from morphology to diagnosis.", "nodes": [{"id": "n1", "label": "New rash", "type": "symptom", "note": "Onset, itch, pain, fever, drugs started in the last 8 weeks, contacts, travel, systemic symptoms.", "link": null, "level": 0}, {"id": "n2", "label": "Primary lesion", "type": "mechanism", "note": "Macule, papule, plaque, vesicle, bulla, pustule, wheal, nodule: the first morphological decision.", "link": null, "level": 1}, {"id": "n3", "label": "Distribution", "type": "mechanism", "note": "Extensor or flexural, dermatomal, photo-exposed, acral, truncal, symmetric or asymmetric.", "link": null, "level": 1}, {"id": "n4", "label": "Scaly plaques", "type": "sign", "note": "Well-demarcated salmon plaques with silvery scale on extensors and scalp: psoriasis (Auspitz sign, Koebner).", "link": "learn/dcond/psoriasis", "level": 2}, {"id": "n5", "label": "Eczematous", "type": "sign", "note": "Ill-defined itchy erythema with lichenification in the flexures: atopic eczema; sharp borders at a contact site: contact dermatitis.", "link": "learn/dcond/atopic", "level": 2}, {"id": "n6", "label": "Annular scaly", "type": "sign", "note": "Ring with an active scaly edge and central clearing: tinea corporis; a herald patch then a fir-tree pattern: pityriasis rosea.", "link": "learn/dcond/tinea", "level": 2}, {"id": "n7", "label": "Wheals", "type": "sign", "note": "Transient itchy swellings lasting under 24 hours each: urticaria; with lip or tongue swelling, consider anaphylaxis or angio-oedema.", "link": "learn/dcond/urticaria", "level": 2}, {"id": "n8", "label": "Vesicles", "type": "sign", "note": "Grouped vesicles on an erythematous base: herpes simplex; a unilateral dermatomal band: zoster.", "link": "learn/dcond/zoster", "level": 2}, {"id": "n9", "label": "Target lesions", "type": "sign", "note": "Three-zone targets on the hands and feet: erythema multiforme, usually after HSV.", "link": "learn/dcond/em", "level": 2}, {"id": "n10", "label": "Purpura", "type": "sign", "note": "Non-blanching red-purple lesions: assess platelets, vasculitis and sepsis.", "link": "learn/dcond/petechiae-plt", "level": 2}, {"id": "n11", "label": "Blisters", "type": "sign", "note": "Tense bullae in the elderly: bullous pemphigoid; flaccid, with mouth erosions and positive Nikolsky: pemphigus.", "link": "learn/dcond/bp", "level": 2}, {"id": "n12", "label": "Diascopy", "type": "test", "note": "Press a glass slide: blanching erythema is vascular dilatation; non-blanching is extravasated blood.", "link": "signs/sign/diascopy", "level": 3}, {"id": "n13", "label": "Nikolsky sign", "type": "test", "note": "Lateral pressure shears the epidermis: positive in pemphigus, SJS/TEN and staphylococcal scalded skin.", "link": "signs/sign/nikolsky", "level": 3}, {"id": "n14", "label": "Meningococcal rash", "type": "diagnosis", "note": "Fever with spreading petechiae or purpura: give antibiotics before any test.", "link": "learn/dcond/meningococcal", "level": 4}, {"id": "n15", "label": "SJS / TEN", "type": "diagnosis", "note": "Painful dusky skin, mucosal erosions and epidermal detachment within 8 weeks of a new drug; stop the drug and refer to burns or dermatology.", "link": "learn/dcond/sjs", "level": 4}, {"id": "n16", "label": "Necrotising fasciitis", "type": "diagnosis", "note": "Pain out of proportion, rapid spread, crepitus, systemic toxicity: surgical emergency.", "link": "learn/dcond/necfasc", "level": 4}, {"id": "n17", "label": "Cutaneous vasculitis", "type": "diagnosis", "note": "Palpable purpura on the legs; check urine for renal involvement.", "link": "learn/dcond/vasculitis", "level": 4}, {"id": "n18", "label": "Wood's lamp", "type": "test", "note": "Coral-red fluorescence in erythrasma, yellow-green in pityriasis versicolor; accentuates vitiligo.", "link": "signs/sign/woods", "level": 3}, {"id": "n19", "label": "Koebner and Auspitz", "type": "sign", "note": "New plaques along scratches, and pinpoint bleeding on removing scale: supportive signs of psoriasis.", "link": "signs/sign/koebner", "level": 3}], "edges": [{"from": "n1", "to": "n2", "label": "name it"}, {"from": "n1", "to": "n3", "label": "map it"}, {"from": "n2", "to": "n4", "label": "plaque"}, {"from": "n2", "to": "n5", "label": "patch"}, {"from": "n2", "to": "n6", "label": "annular"}, {"from": "n2", "to": "n7", "label": "wheal"}, {"from": "n2", "to": "n8", "label": "vesicle"}, {"from": "n2", "to": "n9", "label": "target"}, {"from": "n2", "to": "n10", "label": "purpura"}, {"from": "n2", "to": "n11", "label": "bulla"}, {"from": "n3", "to": "n4", "label": "extensor"}, {"from": "n3", "to": "n5", "label": "flexural"}, {"from": "n3", "to": "n8", "label": "dermatomal"}, {"from": "n10", "to": "n12", "label": "test"}, {"from": "n11", "to": "n13", "label": "test"}, {"from": "n12", "to": "n14", "label": "with fever"}, {"from": "n12", "to": "n17", "label": "palpable"}, {"from": "n13", "to": "n15", "label": "positive"}, {"from": "n1", "to": "n16", "label": "pain, toxic"}, {"from": "n6", "to": "n18", "label": "test"}, {"from": "n4", "to": "n19", "label": "supports"}], "quiz": [{"q": "What is the first question to answer when describing any rash?", "a": "The primary lesion: macule, papule, plaque, vesicle, bulla, pustule, wheal or nodule."}, {"q": "What does a positive Nikolsky sign indicate and in which conditions?", "a": "Intra-epidermal or sub-epidermal splitting with lateral pressure; pemphigus, SJS/TEN and staphylococcal scalded skin syndrome."}, {"q": "A febrile patient has petechiae that do not blanch under a glass. What do you do?", "a": "Give antibiotics immediately for presumed meningococcal sepsis, before investigations."}]}, {"id": "pigmented-lesion", "title": "The pigmented lesion: rules, dermoscopy and the decision", "sys": "derm", "intro": "Melanoma is suspected from the ABCDE and Glasgow 7-point criteria, the 'ugly duckling' sign and the EFG rule for nodular melanoma, then refined by dermoscopy, and the decision is excision with a 2 mm margin, never a shave. The map lays out each rule, what it detects and what it misses.", "nodes": [{"id": "n1", "label": "Pigmented lesion", "type": "symptom", "note": "New, changing or symptomatic mole; age, sun exposure, skin type, family history and number of naevi set the prior.", "link": null, "level": 0}, {"id": "n2", "label": "ABCDE", "type": "test", "note": "Asymmetry, Border irregularity, Colour variation, Diameter over 6 mm, Evolving: screens superficial spreading melanoma.", "link": "signs/sign/abcde", "level": 1}, {"id": "n3", "label": "Glasgow 7-point", "type": "test", "note": "Major: change in size, shape, colour; minor: inflammation, crusting or bleeding, sensory change, diameter 7 mm or more. Any major or 3 points: refer.", "link": "signs/sign/abcde", "level": 1}, {"id": "n4", "label": "EFG rule", "type": "test", "note": "Elevated, Firm, Growing for more than a month: catches nodular melanoma, which fails ABCDE.", "link": null, "level": 1}, {"id": "n5", "label": "Ugly duckling", "type": "sign", "note": "A lesion that does not look like the patient's other moles; comparison beats absolute criteria.", "link": null, "level": 1}, {"id": "n6", "label": "Dermoscopy", "type": "test", "note": "Magnified, polarised view of pigment structure; raises sensitivity and specificity in trained hands.", "link": "signs/sign/dermoscopy", "level": 2}, {"id": "n7", "label": "Melanoma features", "type": "sign", "note": "Asymmetric pigment network, blue-white veil, irregular dots and streaks, regression structures, atypical vessels.", "link": null, "level": 3}, {"id": "n8", "label": "Benign patterns", "type": "sign", "note": "Symmetric network, homogeneous pattern, comedo-like openings and milia-like cysts (seborrhoeic keratosis), central white patch (dermatofibroma).", "link": "learn/dcond/sk", "level": 3}, {"id": "n9", "label": "Melanoma", "type": "diagnosis", "note": "Malignant melanocytes; prognosis depends on Breslow thickness, so early diagnosis matters more than any treatment.", "link": "learn/dcond/melanoma", "level": 4}, {"id": "n10", "label": "Melanocytic naevus", "type": "diagnosis", "note": "Benign mole: symmetric, uniform, stable; most pigmented lesions.", "link": "learn/dcond/naevus", "level": 4}, {"id": "n11", "label": "Seborrhoeic keratosis", "type": "diagnosis", "note": "Stuck-on, waxy, warty plaque with keratin plugs; the commonest melanoma mimic.", "link": "learn/dcond/sk", "level": 4}, {"id": "n12", "label": "Pigmented BCC", "type": "diagnosis", "note": "Pearly rolled edge with arborising vessels and blue-grey ovoid nests.", "link": "learn/dcond/bcc", "level": 4}, {"id": "n13", "label": "Dermatofibroma", "type": "diagnosis", "note": "Firm nodule that dimples on pinching; central white scar-like patch on dermoscopy.", "link": "learn/dcond/df", "level": 4}, {"id": "n14", "label": "Excision biopsy", "type": "decision", "note": "Suspected melanoma: full-thickness excision with a 2 mm margin for histology; never shave, curette or partially sample.", "link": null, "level": 4}, {"id": "n15", "label": "Urgent referral", "type": "decision", "note": "Two-week-wait referral for any lesion scoring 3 or more on the 7-point list or with dermoscopic concern.", "link": null, "level": 4}, {"id": "n16", "label": "Reassure and photograph", "type": "decision", "note": "Benign pattern: reassure, teach self-examination and photograph if the patient or you want a baseline.", "link": null, "level": 4}], "edges": [{"from": "n1", "to": "n2", "label": "apply"}, {"from": "n1", "to": "n3", "label": "apply"}, {"from": "n1", "to": "n4", "label": "apply"}, {"from": "n1", "to": "n5", "label": "compare"}, {"from": "n2", "to": "n6", "label": "then"}, {"from": "n3", "to": "n6", "label": "then"}, {"from": "n4", "to": "n6", "label": "then"}, {"from": "n5", "to": "n6", "label": "then"}, {"from": "n6", "to": "n7", "label": "suspicious"}, {"from": "n6", "to": "n8", "label": "reassuring"}, {"from": "n7", "to": "n9", "label": "suggests"}, {"from": "n8", "to": "n10", "label": "naevus"}, {"from": "n8", "to": "n11", "label": "SK"}, {"from": "n8", "to": "n13", "label": "DF"}, {"from": "n7", "to": "n12", "label": "vessels"}, {"from": "n9", "to": "n15", "label": "refer"}, {"from": "n9", "to": "n14", "label": "excise"}, {"from": "n10", "to": "n16", "label": "manage"}, {"from": "n11", "to": "n16", "label": "manage"}, {"from": "n3", "to": "n15", "label": "3+ points"}], "quiz": [{"q": "Which type of melanoma does the ABCDE rule miss, and what rule catches it?", "a": "Nodular melanoma; the EFG rule (Elevated, Firm, Growing over a month)."}, {"q": "Name three dermoscopic features suggesting melanoma.", "a": "Atypical asymmetric pigment network, blue-white veil, irregular dots or streaks (also regression structures, atypical vessels)."}, {"q": "How should a suspected melanoma be biopsied?", "a": "Full-thickness excision with a 2 mm margin; never a shave or partial biopsy."}]}, {"id": "thyroid", "title": "Thyroid: hyper and hypo, mechanism to sign to test", "sys": "hn", "intro": "Thyroid hormone sets metabolic rate and sympathetic sensitivity, so excess and deficiency produce mirror-image signs across the pulse, skin, reflexes and eyes. The map links each sign to its mechanism, separates Graves' from other causes, and ends in the tests that confirm the diagnosis.", "nodes": [{"id": "n1", "label": "Thyroid disease", "type": "diagnosis", "note": "Suspected from weight change, heat or cold intolerance, palpitations, bowel and menstrual change, or a neck lump.", "link": null, "level": 0}, {"id": "n2", "label": "Hyperthyroidism", "type": "diagnosis", "note": "Graves', toxic multinodular goitre, toxic adenoma, thyroiditis or amiodarone.", "link": null, "level": 1}, {"id": "n3", "label": "Hypothyroidism", "type": "diagnosis", "note": "Hashimoto's thyroiditis, post-ablation, iodine deficiency, lithium or amiodarone.", "link": null, "level": 1}, {"id": "n4", "label": "Increased beta-adrenergic sensitivity", "type": "mechanism", "note": "Thyroxine upregulates beta receptors: tachycardia, tremor, lid retraction, sweating.", "link": null, "level": 2}, {"id": "n5", "label": "Raised metabolic rate", "type": "mechanism", "note": "Heat intolerance, weight loss despite appetite, proximal myopathy, diarrhoea.", "link": null, "level": 2}, {"id": "n6", "label": "Reduced metabolic rate", "type": "mechanism", "note": "Cold intolerance, weight gain, constipation, bradycardia, slowed mentation.", "link": null, "level": 2}, {"id": "n7", "label": "Glycosaminoglycan deposition", "type": "mechanism", "note": "Myxoedema: coarse dry skin, puffy face, hoarse voice, non-pitting oedema.", "link": null, "level": 2}, {"id": "n8", "label": "Autoimmunity (Graves')", "type": "mechanism", "note": "TSH-receptor antibodies stimulate the gland and orbital fibroblasts: diffuse goitre with bruit, eye disease, pretibial myxoedema.", "link": null, "level": 2}, {"id": "n9", "label": "Lid retraction and lag", "type": "sign", "note": "Sclera visible above the iris and the lid lags the eye on downward gaze: sympathetic overactivity, any cause of thyrotoxicosis.", "link": "signs/sign/hyperthyroid-signs", "level": 3}, {"id": "n10", "label": "Fine tremor and warm hands", "type": "sign", "note": "Tremor on a sheet of paper over the outstretched hands; warm, moist palms; palmar erythema.", "link": null, "level": 3}, {"id": "n11", "label": "Tachycardia or AF", "type": "sign", "note": "Resting tachycardia; atrial fibrillation in older patients may be the only presenting feature.", "link": "signs/sign/irregular-pulse", "level": 3}, {"id": "n12", "label": "Exophthalmos and ophthalmoplegia", "type": "sign", "note": "Proptosis, chemosis and restricted upgaze are specific to Graves' orbitopathy, not to thyrotoxicosis itself.", "link": null, "level": 3}, {"id": "n13", "label": "Delayed ankle reflex", "type": "sign", "note": "Slow relaxation phase of the ankle jerk: the most specific sign of hypothyroidism.", "link": "signs/sign/hypothyroid-signs", "level": 3}, {"id": "n14", "label": "Bradycardia and coarse skin", "type": "sign", "note": "Slow pulse, dry cool skin, loss of the outer eyebrows, periorbital puffiness.", "link": "signs/sign/hypothyroid-signs", "level": 3}, {"id": "n15", "label": "Goitre", "type": "sign", "note": "Diffuse and smooth in Graves' and Hashimoto's; nodular in multinodular goitre; a single nodule needs ultrasound.", "link": "signs/sign/thyroid-palp", "level": 3}, {"id": "n16", "label": "Pemberton's sign", "type": "sign", "note": "Facial plethora and stridor on raising the arms: a retrosternal goitre obstructing the thoracic inlet.", "link": "signs/sign/pemberton", "level": 3}, {"id": "n17", "label": "TSH and free T4", "type": "test", "note": "Low TSH with high T4: primary hyperthyroidism; high TSH with low T4: primary hypothyroidism; TSH alone screens.", "link": null, "level": 4}, {"id": "n18", "label": "Antibodies and uptake scan", "type": "test", "note": "TSH-receptor antibodies confirm Graves'; uptake scan separates Graves' (diffuse) from nodules (focal) and thyroitis (low).", "link": null, "level": 4}], "edges": [{"from": "n1", "to": "n2", "label": "excess"}, {"from": "n1", "to": "n3", "label": "deficiency"}, {"from": "n2", "to": "n4", "label": "causes"}, {"from": "n2", "to": "n5", "label": "causes"}, {"from": "n2", "to": "n8", "label": "Graves'"}, {"from": "n3", "to": "n6", "label": "causes"}, {"from": "n3", "to": "n7", "label": "causes"}, {"from": "n4", "to": "n9", "label": "produces"}, {"from": "n4", "to": "n10", "label": "produces"}, {"from": "n4", "to": "n11", "label": "produces"}, {"from": "n8", "to": "n12", "label": "produces"}, {"from": "n8", "to": "n15", "label": "diffuse"}, {"from": "n6", "to": "n13", "label": "produces"}, {"from": "n6", "to": "n14", "label": "produces"}, {"from": "n7", "to": "n14", "label": "produces"}, {"from": "n3", "to": "n15", "label": "Hashimoto's"}, {"from": "n15", "to": "n16", "label": "retrosternal"}, {"from": "n2", "to": "n17", "label": "confirm"}, {"from": "n3", "to": "n17", "label": "confirm"}, {"from": "n2", "to": "n18", "label": "cause"}], "quiz": [{"q": "Which eye signs occur in any cause of thyrotoxicosis and which are specific to Graves'?", "a": "Lid retraction and lid lag occur in any cause; exophthalmos, chemosis and ophthalmoplegia are specific to Graves' orbitopathy."}, {"q": "What is the most specific bedside sign of hypothyroidism?", "a": "Delayed relaxation of the ankle reflex."}, {"q": "What does Pemberton's sign indicate?", "a": "A retrosternal goitre obstructing the thoracic inlet when the arms are raised."}]}];
